(10, 13, 1, 1, '2026-01-17 01:25:19', '2026-01-17 01:27:19', 0);
INSERT INTO `capitulos` (`id_capitulo`, `id_libro`, `titulo`, `imagen`, `contenido`, `glosario`) VALUES
(1, 1, 'Capítulo 1', 'imagenes/laciudadylosperros/CiudadPerros_cap_1.jpg', 'El Esclavo permanecía en la garita, inmóvil, mientras la noche caía sobre el colegio militar como un manto sofocante. El patio estaba cubierto por una neblina tenue que difuminaba las sombras, haciendo que los corredores parecieran más largos, más vacíos. El silencio estaba cargado de ruidos lejanos, murmullos casi imperceptibles, como si el edificio entero respirara.\r\nDesde que llegó al Leoncio Prado había esperado encontrar orden y camaradería, pero lo que halló fueron humillaciones constantes y golpes disfrazados de enseñanza. En ese lugar no existían amigos; solo alianzas frágiles, pactos temporales para sobrevivir. Pensó en su madre y en su casa, tan lejana, y sintió un nudo que lo dejaba sin aire. Allí, cualquier muestra de debilidad se pagaba caro.\r\nLa oscuridad parecía viva; en cada rincón se escondían amenazas invisibles. Sabía que la verdadera jerarquía no la marcaban los oficiales, sino el Jaguar y el Círculo, que imponían sus propias reglas. El miedo era la moneda diaria, el precio inevitable de convivir con la brutalidad. Mientras sostenía el fusil con manos tensas, creyó que la noche no acabaría nunca, que aquel silencio opresivo sería eterno, como la sensación de estar atrapado en un sitio que no lo dejaría escapar.', 'Inmóvil → Que no se mueve; permanece quieto.\r\nDifuminaba → Hacer que algo pierda nitidez o claridad.\r\nJerarquía → Orden o estructura de poder entre personas o cargos.\r\nOpresivo → Que causa angustia o sensación de peso.\r\nBrutalidad → Comportamiento cruel o violento.'),
(2, 1, 'Capítulo 2', 'imagenes/laciudadylosperros/CiudadPerros_cap_2.jpg', 'Cava avanzaba con cautela, pegado a las paredes rugosas y húmedas del colegio militar. La neblina espesa cubría a los corredores como un manto opaco, distorsionando las sombras y haciendo que cada rincón pareciera acechar. Sus pasos eran sigilosos, medidos con precisión, temiendo que el más leve sonido lo delatara. Sabía que un error significaba no sólo la expulsión, sino también el desprecio implacable del Jaguar. Su corazón golpeaba con un ritmo irregular, como si quisiera escapar de su pecho.\r\nAl llegar a las aulas, extrajo la lima con manos tensas y la introdujo en la rendija de la ventana. El chirrido del metal cortó el silencio como un reproche. Contuvo la respiración. Empujó la ventana y un aire viciado y pesado lo envolvió al entrar. Encendió la linterna y la luz temblorosa iluminó el examen de Química. Copió las preguntas con prisa febril, sin detenerse a comprenderlas.\r\nAl saltar para huir, un vidrio estalló con un sonido seco. Se paralizó, esperando pasos, voces, algo… pero no hubo nada. Guardó los fragmentos en el bolsillo y escapó. En el baño lo esperaba el Jaguar, con mirada gélida. Lo tomó por las solapas, lo insultó y sentenció: “Si nos descubren, te vas solo”. Mientras tanto, Alberto cumplía guardia, miró al Esclavo con desprecio y juntos robaron un sacón. La noche siguió densa, vigilante.\r\n', 'Sigilosos → Que actúa con cuidado y sin hacer ruido.\r\nImplacable → Que no muestra compasión ni perdón.\r\nReproche → Expresión de desaprobación o censura.\r\nTemblorosa → Que tiembla o se mueve con inestabilidad.\r\nGélida → Extremadamente fría, o figuradamente, sin emociones.'),
(3, 1, 'Capítulo 3', 'imagenes/laciudadylosperros/CiudadPerros_cap_3.jpg', 'Cava avanzaba con pasos contenidos, pegado a las paredes húmedas de la cuadra. El aire nocturno era cortante y la neblina envolvía los corredores como un velo opaco, deformando las sombras. No temblaba por el frío sino por la expectativa opresiva que siempre precedía a las órdenes del Jaguar. En el Leoncio Prado nada era voluntario: el azar de los dados había decidido su destino y, si fallaba, no habría clemencia, solo represalias silenciosas pero implacables. \r\nLa cuadra dormía en un murmullo monótono, roto apenas por ronquidos aislados y un olor rancio que emanaba de los baños cercanos. Cada paso resonaba en su cabeza como un recordatorio de que, en ese colegio, más que disciplina, reinaba una jerarquía salvaje. Las rendijas del techo dejaban pasar un viento gélido que le erizaba la piel, como si el edificio mismo respirara. Allí, la humillación era una moneda diaria. Los fuertes imponían su ley con una mezcla de violencia y astucia; los débiles sobrevivían en silencio. Cava, que conocía el frío de la sierra, nunca había sentido uno tan profundo, un frío que no nacía del clima sino del miedo que lo paralizaba desde dentro.\r\n', 'Opresiva → Que causa angustia o sensación de peso emocional.\r\nRepresalias → Castigos tomados como venganza.\r\nImplacables → Que no muestran piedad ni compasión.\r\nAstucia → Habilidad para conseguir algo usando ingenio o engaño.\r\nJerarquía → Organización de poder en niveles o rangos.\r\n'),
(4, 1, 'Capítulo 4', 'imagenes/laciudadylosperros/CiudadPerros_cap_4.jpg', 'Alberto vuelve a casa y se enfrenta a un ambiente cargado. Su madre, frágil y melancólica, le habla del pasado con nostalgia: evoca su juventud brillante, los viajes, las amistades perdidas y el matrimonio que ahora la consume. Entre lágrimas, confiesa que su esposo, el padre de Alberto, ha regresado tras años de ausencia, trayendo promesas de reconciliación que ella rechaza. Alberto escucha en silencio, atrapado entre la compasión por su madre y el resentimiento hacia ese hombre ausente. \r\nMientras ella se desahoga, Alberto se siente atrapado en dos mundos: el violento y jerárquico colegio militar y esta casa silenciosa, impregnada de recuerdos rotos. Recibe un sobre con dinero, la única muestra de afecto indirecto de su padre. Él abraza a su madre, finge optimismo, pero en su mente solo piensa en la Pies Dorados, en el Esclavo, en el colegio. La calidez del hogar no logra disipar el peso del Leoncio Prado ni las culpas que arrastra. La escena mezcla ternura y desolación: una madre aferrada a un hijo como único apoyo, un muchacho que ya no se siente niño, y un vínculo familiar carcomido por el abandono.\r\n', 'Evoca → Traer al presente un recuerdo o imagen del pasado.\r\nRechaza → Negarse a aceptar algo o a alguien.\r\nImpregnada → Llena o saturada de algo (por ejemplo, emociones o recuerdos).\r\nCarcomido → Deteriorado o consumido lentamente, literal o simbólicamente.\r\nAbandono → Falta de cuidado o afecto; dejar solo a alguien emocional o físicamente.'),
(5, 1, 'Capítulo 5', 'imagenes/laciudadylosperros/CiudadPerros_cap_5.jpg', 'Alberto avanzaba por las avenidas de Miraflores acompañado de sus amigos de infancia, muchachos de gestos despreocupados y risas fáciles. Las fachadas ostentosas, los jardines geométricamente podados y el perfume salobre del mar parecían pertenecer a otra ciudad, una tan distinta al Leoncio Prado que casi le resultaba ilusoria. El grupo conversaba de trivialidades, lanzaba comentarios mordaces sobre las muchachas que pasaban y celebraba con carcajadas anécdotas que a Alberto le sonaban huecas. \r\nMientras fingía atención, su mente vagaba. Seguía encadenada a los pasillos sombríos del colegio militar, al tono helado del Jaguar, al murmullo nervioso del Esclavo. Esa supuesta libertad que respiraba en Miraflores le resultaba un escenario artificioso, apenas un velo superficial que ocultaba otras jerarquías, otras formas de sometimiento.\r\nEntonces apareció Teresa. No lucía la afectación altiva de las demás. Hablaba poco, movía las manos con una delicadeza casi involuntaria, y sus ojos parecían guardar silencios más hondos que cualquier palabra. Su discreción desentonaba con la frivolidad del paseo. Alberto la miró sin atreverse a romper esa distancia, sintiendo un extraño sosiego que no comprendía. Mientras el grupo seguía su ronda de bromas y chismes, él comprendió que en ningún espacio —ni en el colegio ni en esas calles pulcras— existía una verdadera libertad, solo cárceles invisibles.', 'Desentonaba → No encajaba con el entorno o el comportamiento de los demás.\r\nDiscreción → Capacidad de actuar con prudencia y sin llamar la atención.\r\nSosiego → Sensación de calma y serenidad interior.\r\nAltiva → Orgullosa o soberbia en la actitud.\r\nSometimiento → Estado de obediencia o subordinación ante una autoridad o presión.'),
(1, 2, 'Capítulo 1', 'imagenes/Dracula/Dracula_cap_1.jpg', 'Desde Londres emprendí mi viaje hacia Transilvania para concretar un negocio con un noble llamado conde Drácula. Al principio, todo parecía rutinario, pero a medida que el tren avanzaba hacia el este, las ciudades se desvanecían y el paisaje se volvía más salvaje y desconocido.\r\nEn cada aldea, los lugareños me miraban con temor al oír el nombre del conde. Algunos me ofrecieron amuletos y me rogaron que no siguiera. Yo lo tomé como simple superstición, aunque un mal presentimiento comenzaba a inquietarme. Al llegar al paso de Borgo, un carruaje negro me esperaba. El cochero, silencioso y extraño, me condujo por senderos oscuros mientras los lobos aullaban alrededor. Bastaba un gesto suyo para hacerlos callar, lo que me heló la sangre.\r\nEl castillo apareció finalmente, erguido sobre un precipicio, sombrío y desolado. Allí me recibió el conde: alto, pálido, de modales exquisitos, pero de una presencia que imponía un miedo inexplicable. Esa noche supe que había cruzado un umbral invisible. Algo en aquel lugar —en su silencio, en la mirada del conde— me hizo entender que estaba lejos de todo lo humano.\r\n', 'Superstición → Creencia irracional en fuerzas o hechos sobrenaturales, generalmente sin base científica.\r\nPrecipicio → Lugar muy alto con una caída abrupta o peligrosa, símbolo del riesgo o el abismo.\r\nLúgubre → Que causa tristeza, miedo o desolación; se usa para describir ambientes oscuros o fúnebres.\r\nAislamiento → Estado de estar separado o incomunicado de los demás, tanto física como emocionalmente.\r\nUmbral → Límite o punto de entrada que separa dos espacios o estados, en este caso, lo humano de lo sobrenatural.'),
(2, 2, 'Capítulo 2', 'imagenes/Dracula/Dracula_cap_2.jpg', 'Desde su llegada al castillo, Jonathan Harker sintió que algo no encajaba. El conde Drácula lo recibía con cortesía, pero su presencia resultaba tan fría y extraña que el joven no podía sentirse en paz. El aire del lugar era denso, y el silencio parecía observarlo.\r\nEl conde hablaba un inglés impecable y mostraba gran interés por Londres y sus costumbres. Conversaba con Jonathan sobre una antigua propiedad que había comprado, Carfax, mientras el joven notaba detalles perturbadores en su aspecto: piel pálida, orejas puntiagudas y uñas afiladas como garras.\r\nUna mañana, al afeitarse, Jonathan descubrió que el conde no se reflejaba en el espejo. Al percatarse, Drácula lo arrancó de su mano y lo estrelló contra la pared con furia, antes de disculparse con una calma aún más inquietante. Desde entonces, el miedo se instaló en Jonathan.\r\nPronto comprendió que todas las puertas estaban cerradas y que no existía ningún sirviente. De noche, los pasillos se llenaban de ruidos y lamentos que parecían surgir de las entrañas del castillo. Las ventanas daban a precipicios imposibles de escalar, y el aislamiento se volvió insoportable.\r\nAunque intentaba conservar la calma y fingir serenidad ante el conde, Jonathan sabía la verdad: estaba atrapado, y su anfitrión no era un hombre común, sino una criatura fuera del alcance de la razón.', 'Perturbador → Que altera o inquieta profundamente los pensamientos o emociones; provoca angustia o temor.\r\nAislamiento → Estado de separación o desconexión del entorno o de otras personas, generando soledad o desesperación.\r\nEspeluznante → Que produce miedo o escalofríos intensos por su carácter aterrador o sobrenatural.\r\nPrecipicio → Terreno con una caída vertical o abrupta, símbolo del peligro o de una situación sin salida.\r\nVulnerable → Que puede ser herido o dañado fácilmente, física o emocionalmente; en el texto, alude a la fragilidad de Jonathan ante Drácula.'),
(3, 2, 'Capítulo 3', 'imagenes/Dracula/Dracula_cap_3.jpg', 'Los días pasaban lentos y la inquietud de Jonathan Harker crecía con cada hora. Las puertas del castillo seguían cerradas, los pasillos vacíos, y el conde Drácula lo observaba con una cortesía tan controlada que resultaba más amenazante que amable. Poco a poco, Jonathan comprendió la verdad: estaba prisionero.\r\nEl conde se mostraba fascinado por Londres. Le pedía a Jonathan que le enseñara las costumbres, los modales y el idioma de un caballero inglés. Incluso lo obligó a escribir cartas fechadas hacia el futuro para hacer creer a su prometida y a su jefe que todo marchaba bien. Entonces, Jonathan entendió que aquel interés escondía un propósito más oscuro.\r\nUna noche, pese a la advertencia de no deambular por el castillo, la curiosidad pudo más que el miedo. Con una lámpara en mano, recorrió los pasillos hasta llegar a una habitación antigua. Allí, el sueño lo venció. En medio de ese sopor, tres mujeres de belleza mortal se acercaron a él; sus miradas ardían de deseo y hambre. Jonathan sintió el corazón detenerse cuando una de ellas inclinó el rostro hacia su cuello.\r\nDe pronto, una figura irrumpió con furia. Era Drácula. Las apartó y, con una voz áspera, les prometió una presa mejor: un niño. Ellas se alejaron entre risas apagadas, dejando a Jonathan paralizado de terror.\r\nAl despertar, no supo si había soñado o si lo vivido era real. Pero el miedo persistía, tan palpable como las paredes del castillo. Desde entonces, escribió su diario con desesperación, aferrándose a las palabras para no perder la razón.\r\n', 'Deambular → Caminar sin rumbo fijo, moviéndose sin un destino claro; simboliza la curiosidad y el riesgo de Jonathan al explorar el castillo.\r\nSeductoras → Que atraen o fascinan intensamente; en el texto, describe a las tres mujeres vampiras cuya belleza es peligrosa y mortal.\r\nParalizado → Estado de inmovilidad total causado por el miedo extremo o la sorpresa; refleja la impotencia de Jonathan ante lo sobrenatural.\r\nSobrenatural → Que excede los límites de la naturaleza o la razón humana; asociado a lo mágico, misterioso o inexplicable.\r\nCordura → Capacidad de mantener la razón y el equilibrio mental; en el relato, es lo que Jonathan intenta conservar frente al horror que vive.'),
(4, 2, 'Capítulo 4', 'imagenes/Dracula/Dracula_cap_4.jpg', 'Encerrado entre los muros del castillo, Jonathan Harker comprendió la verdad: era un prisionero. Ninguna puerta cedía y el conde Drácula lo vigilaba con una cortesía tan fría como inhumana. Cada día, el miedo crecía con el silencio.\r\nIntentó huir en vano. Descubrió que no había sirvientes: el conde hacía todo, moviéndose con una agilidad imposible. Una noche lo vio descender por el muro, como una sombra bajo la luna, y entendió que no era un hombre.\r\nApegado a su diario, Jonathan registraba su encierro y evitaba cualquier alimento ajeno. En una habitación secreta halló la biblioteca del conde y supo de su linaje valaco, su pasado de guerrero y su ambición de dominar Inglaterra.\r\nPor las noches, los gritos en los pasillos confirmaban sus temores. Una vez, vio al conde marcharse con un saco que se movía: comprendió, horrorizado, que dentro había un niño.\r\nCon el viaje del conde más cercano, Jonathan decidió arriesgarlo todo y escapar por los muros. En su última nota, solo dejó su esperanza: que alguien encontrara su diario y conociera la verdad sobre Drácula.\r\n', 'Linaje → Origen o ascendencia familiar, especialmente de carácter noble; revela el pasado histórico y orgulloso del conde Drácula.\r\nValaco → Relativo a Valaquia, antigua región de Rumania; da contexto geográfico y cultural al origen del conde.\r\nAmasado → Acumulado con el tiempo, ya sea conocimiento, poder o riqueza; refleja la larga vida y experiencia del conde.\r\nLamentos → Sonidos o gritos de dolor profundo; intensifican el ambiente de terror y sufrimiento dentro del castillo.\r\nManuscrito → Documento escrito a mano; en el texto, simboliza el último intento de Jonathan por dejar testimonio y preservar la verdad.'),
(5, 2, 'Capítulo 5', 'imagenes/Dracula/Dracula_cap_5.jpg', 'Lejos de los montes de Transilvania, el viento del mar soplaba en Whitby. Mina Murray pasaba sus días mirando el horizonte, esperando una carta que no llegaba. Jonathan seguía ausente, perdido en su misterioso viaje, y aunque ella intentaba llenar el silencio aprendiendo taquigrafía o paseando por los acantilados, la inquietud se le colaba en el alma como una sombra.\r\nLucy Westenra, su amiga más cercana, vivía días más luminosos. Tres hombres la habían pedido en matrimonio en una sola jornada: Arthur Holmwood, refinado y noble, a quien su corazón eligió; el doctor Seward, sereno y razonable; y Quincey Morris, un aventurero venido de tierras lejanas. Lucy los apreciaba a todos con una dulzura que desarmaba el rechazo.\r\nEntre las cartas que ambas intercambiaban corría la vida cotidiana, risueña y apacible, como si el mundo no escondiera secretos. Pero en el aire costero de Whitby empezaban a levantarse señales extrañas: un cielo que cambiaba con brusquedad, un presentimiento sin nombre. Algo oscuro se acercaba, aunque ninguna de las dos lo supiera todavía.\r\n', 'Taquigrafía → Sistema de escritura rápida mediante signos abreviados; representa el deseo de Mina por ocupar su mente y aprender algo útil.\r\nCorrespondencia → Intercambio de cartas que refleja los vínculos afectivos y la comunicación íntima entre las protagonistas.\r\nÉpoca victoriana → Periodo histórico del reinado de la reina Victoria, caracterizado por su moral estricta y avances sociales, que enmarca el contexto de la historia.\r\nCostera → Relacionada con la costa o el mar; sitúa el escenario en Whitby, un punto clave entre lo cotidiano y lo sobrenatural.\r\nInquieta → Que siente ansiedad o presentimiento; expresa el estado emocional de Mina ante la ausencia de Jonathan y los presagios que se avecinan.'),
(1, 3, 'Capítulo 1', 'imagenes/El monstruo de frankenstein/Frankenstein_cap_1.jpg', 'Bajo el resplandor helado del Ártico, Victor Frankenstein comenzó a hablar. Su voz, cansada pero firme, rompía el silencio mientras relataba su vida al hombre que lo había rescatado del hielo. En aquel rincón del mundo, su historia sonaba como una confesión nacida del remordimiento.\r\nContó que nació en Ginebra, hijo de Alphonse Frankenstein y Caroline Beaufort, un matrimonio unido por la compasión. Creció en un hogar lleno de amor y principios. Durante un viaje, su madre halló a una niña huérfana en una aldea italiana: Elizabeth Lavenza, a quien adoptó con ternura.\r\nDesde entonces, Elizabeth fue la luz de su vida: bella y serena, opuesta a la pasión inquieta que lo dominaba. Mientras ella soñaba con la armonía, Victor se sumergía en los libros de Agrippa y Paracelso, obsesionado con los secretos de la naturaleza.\r\nSus padres alentaban su curiosidad sin saber que en ella germinaba un deseo más oscuro: traspasar los límites del conocimiento. Así comenzó el destino de Victor Frankenstein, entre el amor y la ambición, entre la inocencia y la sombra.\r\n', 'Resplandor: Luz intensa que brilla o se refleja.\r\nRemordimiento: Sentimiento de culpa o pesar por una falta cometida.\r\nCompasión: Sentimiento de empatía y deseo de aliviar el sufrimiento ajeno.\r\nObsesionado: Dominado por una idea o pensamiento constante y difícil de apartar.\r\nAmbición: Deseo intenso de alcanzar poder, éxito o conocimiento.'),
(2, 3, 'Capítulo 2', 'imagenes/El monstruo de frankenstein/Frankenstein_cap_2.jpg', 'La infancia de Victor Frankenstein transcurrió entre los jardines tranquilos de Ginebra, acompañado por Elizabeth, serena y bondadosa, y Henry Clerval, soñador de gestas heroicas. Mientras ellos se deleitaban con la poesía y las historias, Victor miraba el mundo con un ansia distinta: deseaba descubrir sus secretos.\r\nSu destino cambió el día que encontró un libro de Cornelio Agrippa. Fascinado por sus ideas sobre la alquimia y la inmortalidad, corrió a mostrárselo a su padre, quien lo despreció como “basura”. Esa indiferencia, más que disuadirlo, encendió su curiosidad. Desde entonces, Victor se hundió en los textos de Paracelso y Alberto Magno, convencido de que la naturaleza escondía fuerzas que solo los valientes podían dominar.\r\nUna noche de tormenta, un rayo destruyó un árbol ante sus ojos. Aquella visión lo estremeció. Comprendió que en la electricidad había poder, energía capaz de animar la materia. Desde ese instante, su fascinación por lo invisible se transformó en obsesión.\r\nLos años pasaron y su mente se volvió un campo de búsqueda incesante. Creía que el conocimiento podía elevar al hombre por encima de sus límites. Sin saberlo, en esa ambición ardiente germinaba ya la semilla de su desgracia.\r\n', 'Fascinado: Atraído intensamente por algo que causa admiración o asombro.\r\nIndiferencia: Falta de interés o emoción ante algo o alguien.\r\nConvencido: Seguro de la verdad de una idea o creencia.\r\nElectricidad: Forma de energía que produce luz, calor o movimiento.\r\nObsesión: Pensamiento o deseo persistente que domina la mente y resulta difícil de controlar.'),
(3, 3, 'Capítulo 3', 'imagenes/El monstruo de frankenstein/Frankenstein_cap_3.jpg', 'El invierno trajo consigo la desgracia al hogar de los Frankenstein. Elizabeth enfermó de escarlatina y, al cuidarla con devoción, Caroline también cayó víctima del mal. Aun debilitada, reunió a sus hijos por última vez, tomó sus manos y les pidió que algún día unieran sus vidas. Su muerte dejó una herida profunda en Victor: fue su primer encuentro con la pérdida, con la idea de que incluso el amor más puro puede ser arrebatado. Esa sombra, silenciosa pero persistente, marcaría su destino y encendería en él el deseo de desafiar la muerte misma.\r\nPoco después, Victor partió hacia Ingolstadt para comenzar sus estudios. Alejarse de su hogar lo llenó de una mezcla de tristeza y emoción: sentía que su verdadera vida recién empezaba. En la universidad conoció a dos maestros que lo influirían de maneras opuestas. M. Krempe, un hombre tosco y arrogante, ridiculizó sus lecturas de los antiguos alquimistas, tachándolos de charlatanes. En contraste, M. Waldman lo recibió con calidez y habló con una pasión contagiosa sobre los descubrimientos modernos. Para él, el científico no solo observaba la naturaleza, sino que la transformaba, se convertía en su “legislador”.\r\nAquel encuentro encendió algo en Victor: una llama intensa y peligrosa. Comenzó a estudiar con una dedicación casi febril, devorando libros de física, química y anatomía. Ya no buscaba solo aprender, sino dominar el misterio de la creación. Cada descubrimiento lo acercaba más a una idea imposible, pero irresistible: vencer a la muerte. Sin saberlo, había dado su primer paso hacia la tragedia que marcaría su vida.\r\n', 'Desafiar: Enfrentarse a algo difícil o intentar superar lo imposible.\r\nRidiculizó: Se burló de algo o de alguien con desprecio.\r\nContagiosa: Que se transmite fácilmente; en sentido figurado, que inspira entusiasmo en otros.\r\nAnatomía: Ciencia que estudia la estructura del cuerpo de los seres vivos.\r\nTragedia: Suceso doloroso o fatal que causa sufrimiento o destrucción.'),
(4, 3, 'Capítulo 4', 'imagenes/El monstruo de frankenstein/Frankenstein_cap_4.jpg', 'En Ingolstadt, la pasión de Victor por la ciencia se transformó en obsesión. Lo que comenzó como curiosidad se volvió una fiebre que lo consumía por completo. Día y noche estudiaba anatomía y química, decidido a descubrir el principio que da vida a los seres. Pronto comprendió que para entender la vida debía mirar de frente a la muerte. Así, comenzó a frecuentar morgues y osarios, observando con fría fascinación los cuerpos en descomposición.\r\nEl mundo exterior dejó de existir. Victor apenas dormía, no comía y ya no escribía a su familia. Todo su ser estaba entregado a un solo propósito: dominar el secreto de la creación. Tras incontables experimentos, creyó haberlo logrado. Poseía —decía— el poder de infundir vida a la materia inerte. Entre el temor y la euforia, se sintió capaz de rozar lo divino.\r\nEntonces decidió construir un ser humano, reuniendo fragmentos de cadáveres y animales. Lo hizo de gran tamaño, para facilitar su trabajo, pero su creación pronto adoptó una forma inquietante. En su delirio, Victor soñaba con la gloria y con ser recordado como el creador de una nueva especie. No veía el horror, sólo la promesa del triunfo.\r\nMientras trabajaba en silencio, su espíritu se quebraba. La criatura estaba casi lista, y Victor se preparaba, febril y tembloroso, para el instante en que su ambición cobrará vida.', 'Morgue: Lugar donde se conservan los cadáveres antes de su entierro o examen.\r\nFascinación: Atracción intensa que algo o alguien ejerce sobre una persona.\r\nEuforia: Estado de ánimo de gran alegría o entusiasmo\r\nAmbición: Deseo intenso de lograr poder, éxito o reconocimiento.\r\nInquietante: Que causa temor o desasosiego por ser extraño o perturbador.'),
(5, 3, 'Capítulo 5', 'imagenes/El monstruo de frankenstein/Frankenstein_cap_5.jpg', 'Aquella noche de noviembre, entre relámpagos y lluvia, Victor Frankenstein culminó su experimento. Tras meses de agotamiento, contempló el cuerpo de su creación. Cuando aplicó la chispa de vida, el ser abrió los ojos: su piel amarillenta y sus labios oscuros borraron toda ilusión de belleza. Donde Victor soñó perfección, encontró el horror.\r\nAterrorizado, huyó bajo la tormenta. Al regresar al amanecer, descubrió que la criatura había desaparecido. Exhausto, cayó enfermo justo cuando su amigo Henry Clerval llegó a Ingolstadt. Sin saber el motivo de su tormento, Henry lo cuidó con paciencia durante semanas de fiebre y delirio.\r\nCon el tiempo, Victor recobró la calma. Una carta de Elizabeth desde Ginebra le devolvió algo de paz, pero la sombra de su creación persistía. Aunque el monstruo había huido, él presentía que su error seguía vivo… y algún día volvería por él.\r\n', 'Relámpago: Destello de luz producido por una descarga eléctrica.\r\nChispa de vida: Momento en que Victor logra dar vida a su creación.\r\nCulminó: Llegó al punto final o máximo de un proceso.\r\nAterrorizado: Lleno de un miedo profundo o incontrolable.\r\nTormento: Sufrimiento o angustia intensa que atormenta el espíritu.'),
(1, 4, 'Capítulo 1', 'dorian1.jpg', 'En un caluroso día de julio, Raskolnikoff bajó las escaleras de su buhardilla en San Petersburgo. Caminaba con sigilo, evitando cruzarse con su patrona, a quien debía meses de alquiler. Su cuerpo estaba débil, su mente confusa, pero una idea fija lo empujaba hacia adelante. Fingía pasear sin rumbo, aunque sabía bien a dónde iba: a la casa de la vieja usurera, Alena Ivanovna. Había empeñado cosas antes, pero ahora el motivo era distinto. En su interior, crecía la sombra de un pensamiento atroz.\r\nEl hambre y la miseria lo habían vuelto huraño, casi delirante. Sentía que el miedo dominaba al mundo más que la pobreza misma. Cuando un borracho se burló de su ridículo sombrero, un pensamiento fugaz lo estremeció: aquel sombrero podría delatarlo si algún día cometía un crimen. El simple comentario confirmó lo que su conciencia temía admitir: ya había empezado a planear un asesinato.\r\nLa casa de la usurera era oscura y sofocante. Raskolnikoff le entregó un reloj para empeñar, mientras sus ojos recorrían el cuarto con precisión: las llaves, los cofres, la anciana. Preguntó por su hermana y supo que al día siguiente no estaría allí. Al salir, un asco profundo lo invadió. Entró en una taberna, bebió una cerveza e intentó convencerse de que todo era una locura pasajera. Pero sabía que no: el crimen ya había nacido en su mente.', 'Buhardilla → Habitación pequeña situada bajo el techo, generalmente pobre o calurosa. | Atroz → Extremadamente cruel o violento. | Huraño → Persona que evita el trato con los demás; poco sociable. | Delatar → Revelar o dejar ver algo oculto, generalmente por descuido. | Sofocante → Que produce sensación de calor o falta de aire.'),
(2, 4, 'Capítulo 2', 'dorian2.jpg', 'Raskolnikoff se sentó en la taberna con una jarra de cerveza entre las manos, buscando apagar el temblor del cuerpo y el caos de la mente. El aire era espeso, cargado de sudor y alcohol, y los murmullos de los borrachos formaban un murmullo triste, como un coro de hombres vencidos. En ese rincón sombrío apareció Marmeládov, un funcionario arruinado por la bebida, de mirada febril y voz quebrada. Sin que nadie lo invitara, se sentó junto a él y comenzó a hablar.\r\nEntre balbuceos y frases grandilocuentes, Marmeládov contó su historia. Había tenido un trabajo, una familia, una vida decente. Pero el alcohol lo había despojado de todo. Su esposa, Katerina Ivanovna, noble empobrecida y enferma, vivía consumiéndose entre la tos y la rabia, mientras los niños, flacos y sucios, lloraban de hambre. La hija mayor, Sonia, se había visto obligada a vender su cuerpo para sostener a todos. Marmeládov lo decía con un orgullo dolido, como si aceptara su propia ruina como un castigo divino. Creía que, al final, Dios acogería a los miserables como él antes que a los justos.\r\nRaskolnikoff lo escuchó en silencio, entre compasión y repulsión. Cuando Marmeládov terminó, dejó sobre la mesa el poco dinero que tenía. Más tarde, al acompañarlo a su casa, vio la miseria hecha carne: la mujer delirante, los niños desnudos, el aire enfermo del lugar. Al salir, el joven sintió un peso nuevo en el alma. Por primera vez, la pobreza y el dolor dejaron de ser ideas; ahora tenían rostro y nombre.', 'Grandilocuente → Que usa un lenguaje exagerado o altisonante para impresionar. | Resignación → Aceptación del sufrimiento o la desgracia sin resistencia. | Fatalismo → Creencia de que el destino está fijado y no puede cambiarse. | Conmiseración → Compasión profunda por el dolor ajeno. | Existencial → Relacionado con las preguntas sobre el sentido de la vida o la culpa.'),
(3, 4, 'Capítulo 3', 'dorian3.jpg', 'De regreso en su cuarto sofocante, Raskolnikoff se dejó caer sobre el catre, vencido por el hambre, el cansancio y el remordimiento. El aire parecía arder, y su mente, agotada, se deshizo en un torbellino de imágenes hasta que cayó en un sueño febril. En su delirio, volvió a ser niño: caminaba junto a su padre por un campo luminoso, pero la escena pronto se volvió pesadilla. Ante sus ojos, unos campesinos borrachos azotaban a una vieja yegua que no podía tirar del carro. \r\nEntre gritos y risas crueles, el hombre llamado Mikolka la golpeó hasta matarla. El pequeño Raskolnikoff, desesperado, abrazó el cuerpo ensangrentado del animal y lloró. Despertó empapado en sudor, temblando. Aquel sueño le reveló su propio horror: la inocencia destruida por la brutalidad humana… y la sombra del crimen que anidaba en su mente.\r\nApenas se repuso, Nastasya, la criada, le entregó una carta de su madre. En ella, Pulqueria Aleksándrovna hablaba con ternura de su hermana Dunia, que había sido humillada por su antiguo patrón y ahora estaba comprometida con Piotr Lujin, un abogado rico y arrogante. Decía que el matrimonio sería su salvación y la de Raskolnikoff. Pero él, al leerla, sintió rabia. Le parecía un sacrificio vergonzoso, una venta disfrazada de honor. La carta, más que consolarlo, avivó su cólera y su desesperación: el mundo, pensó, estaba podrido de miseria e hipocresía, y quizá solo un acto extremo podría romper su maldición.', 'Delirio → Estado mental alterado en el que la persona confunde realidad y fantasía. | Simbólico → Que representa algo más profundo; la yegua encarna violencia y pérdida de inocencia. | Manipulador → Que usa el poder y la conveniencia para controlar a otros. | Dilema existencial → Conflicto moral sobre el bien, el mal y el propio destino. | Resignado → Que acepta con dolor lo injusto para sobrevivir.'),
(4, 4, 'Capítulo 4', 'dorian4.jpg', 'Salió de la pieza con la carta aún ardiendo en la cabeza y anduvo sin rumbo por la ciudad, con la rabia clavada como un dardo. Pensaba en Dunia como si la viera ahí mismo, ofreciendo su dignidad por pan, y Lujin le parecía un comerciante de almas: frío, orgulloso, dispuesto a comprar sumisión. El calor pegaba, las calles olían a polvo y a pobreza, y en cada esquina Raskolnikoff argumentaba para sí la falsedad del mundo.\r\nLa idea del crimen, que hasta entonces era ruido en su mente, empezó a afilarse en razones: la vieja usurera era un parásito, pensó, y su dinero podía devolver dignidad a muchos. Cuando oyó a dos hombres debatir en una taberna la misma hipótesis —matar a la usurera para usar su riqueza en el bien común— le pareció una confirmación, casi un destino. Más tarde, al socorrer a una joven humillada por la calle y ver cómo la policía la ignoraba, sintió que la ciudad devoraba a los débiles. Exhausto, volvió a su cuarto; el cuerpo flaqueaba, pero la decisión se solidificaba: lo que antes era posibilidad, ahora le parecía inevitable.', 'Justificación moral → Razonamiento ético torcido al intentar legitimar el crimen por el bien común. | Catalizador → Detonante que transforma el pensamiento en decisión. | Desesperación económica → La pobreza como fuerza que empuja hacia lo inmoral. | Perturbado → Estado psicológico dividido entre culpa, rabia y racionalización. | Ultrajada → Ofendida o humillada gravemente.'),
(5, 4, 'Capítulo 5', 'dorian5.jpg', 'En la fiebre de la habitación, Raskolnikoff revivía la charla de la taberna como si alguien hubiese puesto en palabras lo que él solo había susurrado a su conciencia. Aquella conversación, que hablaba de matar a la vieja por un bien mayor, dejó de ser un eco ajeno y se volvió argumento propio. Al día siguiente, aún tambaleante, lo fortuito le sonrió: al pasar escuchó a Aliona Ivánovna decirle a su criada que estaría sola por la tarde; la noticia cayó sobre él como una puerta abierta.\r\nDe repente, los jirones de su moral se ordenaron en un plan con hora y lugar. Pensó en el dinero como llave para la libertad: estudios, ayuda para su madre y Dunia, una salida a la miseria. Deshumanizó a la usurera en su mente —\"parásito\", \"molestia\"— y transformó el asesinato en cálculo frío. A veces asomaba la náusea, un destello de duda, pero pronto cedía ante la convicción que crecía en él. Cuando el capítulo termina, oculta junto al cuerpo la decisión tomada: en su ropa, un pequeño hacha espera la tarde señalada.', 'Deshumanización → Proceso de ver a una persona como objeto, no como ser humano. | Náusea moral → Asco o conflicto interior frente al mal que se sabe posible. | Legitimar → Acto de intentar justificar lo injustificable. | Despersonalización → Estado psicológico en que se distancia de sí mismo y su empatía. | Fanatismo → Convicción extrema que transforma su crimen en una misión idealista.'),
(1, 5, 'Capítulo 1', 'imagenes/Mujercitas/Mujercitas_cap_1.jpg', 'Navidad no será Navidad sin regalos —murmuró Jo desde la alfombra. Meg, Amy y Beth suspiraron también, lamentando su pobreza y la ausencia de su padre, lejos en la guerra. Aunque cada una deseaba algo —un libro, música, lápices—, decidieron gastar su dinero en un regalo para su madre.\r\nMientras la nieve caía fuera, ensayaban una obra escrita por Jo. Ella recitaba con dramatismo, Amy actuaba rígidamente, y Beth olvidaba el pan por mirar la escena. El ensayo terminó entre risas, justo cuando entró su madre.\r\nLa señora March, envuelta en su capa gris, fue recibida con cariño. No era hermosa según el mundo, pero para sus hijas era la mujer más espléndida. Se puso las zapatillas calientes que Beth había preparado y, con Amy en las rodillas, se sentó a disfrutar su momento favorito del día.\r\nCada hija se movía por la casa a su modo: Meg preparaba el té, Jo traía leña con torpeza, Beth iba y venía en silencio, y Amy daba órdenes sin moverse. A pesar de las penas y las diferencias, el hogar vibraba con calidez, esfuerzo y afecto sincero.\r\n—Tengo una grata sorpresa después de la cena —dijo la señora March, y los ojos de todas brillaron.\r\n', 'Ausencia → Falta o alejamiento prolongado de una persona querida.\r\nEspléndida → Magnífica o admirable por su carácter o apariencia.\r\nCalidez → Sensación de afecto y ternura en un ambiente o persona.\r\nAfecto sincero → Cariño verdadero, sin falsedad.\r\nGrata sorpresa → Noticia o hecho agradable e inesperado.'),
(2, 5, 'Capítulo 2', 'imagenes/Mujercitas/Mujercitas_cap_2.jpg', 'En esta entrañable Navidad, las hermanas March demuestran su generosidad al regalar su desayuno a una familia pobre. Aunque renuncian a lujos, se llenan de alegría al sorprender a su madre con pequeños obsequios hechos a mano, que ella agradeció con emoción. Por la tarde, organizan una divertida obra teatral en casa. \r\nJo interpreta varios papeles masculinos con gran entusiasmo, y junto a sus hermanas crean disfraces, escenografía y efectos especiales con ingenio. La función está llena de accidentes cómicos —como la caída de una torre de cartón o una cama que atrapa al público—, lo que provoca risas y entusiasmo entre sus amigas.\r\n\r\nLa noche culminó con una cena sorpresa enviada por el señor Laurence, el vecino solitario, enternecido por el gesto de las chicas hacia los pobres. Las hermanas, sorprendidas y felices, celebran rodeadas de dulces, flores y un ambiente cálido. Se menciona al nieto del señor Laurence, un chico tímido con quien Jo desea hacerse amiga. Al final, entre risas y reflexiones, Beth expresa su deseo de compartir su felicidad con su padre ausente, recordando que el verdadero espíritu navideño nace del amor, la solidaridad y la esperanza.', 'Reflexión → Pensamiento profundo sobre una situación o sentimiento.\r\nSolidaridad → Ayuda desinteresada hacia personas en situación de necesidad.\r\nEntusiasmo → Emoción intensa con la que se realiza una actividad.\r\nObsequio → Regalo que se ofrece a otra persona como muestra de afecto.\r\nGenerosidad → Compartir con los demás sin esperar nada a cambio.'),
(3, 5, 'Capítulo 3', 'imagenes/Mujercitas/Mujercitas_cap_3.jpg', 'Jo acompaña a su hermana Meg a un elegante baile. Aunque Meg luce perfecta, Jo se siente insegura por un vestido remendado y unos guantes prestados. En el lugar conocen a Laurie, un joven educado y observador. Jo, intentando no mover mucho su vestido quemado, se niega a bailar, pero Laurie la invita a hacerlo en un pasillo apartado. Allí, bailan alegremente una polca, y Jo aprende un paso nuevo con entusiasmo.\r\nLa noche se complica cuando Meg se tuerce el tobillo por culpa de sus tacones altos. Sin querer preocupar a nadie, decide esperar sentada mientras Jo le busca café. Jo, siempre torpe, derrama la bebida y ensucia su vestido y guantes. Laurie aparece oportunamente con café y helado para ambas, y pasa a ser considerado un joven muy simpático por Meg.\r\nAl final del baile, Laurie ofrece su carruaje para llevarlas a casa, ya que empieza a llover. En el viaje, las chicas comentan la velada con risas y anécdotas. Al llegar, despiertan a Beth y Amy, que ansiosas piden detalles del baile. Jo comparte dulces, y Meg, entre bromas, comenta que se siente como toda una dama al regresar en coche y ser atendida como si tuviera doncella.', 'Velada → Noche especial, generalmente con fiesta o reunión social.\r\nRemendado → Algo que ha sido arreglado con costuras porque estaba roto.\r\nPolka → Baile alegre de origen europeo, con pasos rápidos y saltos.\r\nCarruaje → Vehículo antiguo tirado por caballos.\r\nDoncella → Mujer joven que servía o acompañaba a otra mujer.'),
(4, 5, 'Capítulo 4', 'imagenes/Mujercitas/Mujercitas_cap_4.jpg', 'Las vacaciones habían terminado, y Meg suspiraba con pesar mientras elegía entre sus trajes gastados. Jo, todavía adormilada, deseaba que siempre fuera Navidad, pero sabía que no servía de nada quejarse. Animaba a su hermana a seguir el ejemplo de su madre y cargar sus responsabilidades con alegría. Meg, sin embargo, se sentía vencida por su pobreza y el trabajo, creyendo que jamás podría disfrutar de la vida como otras jóvenes. Esa mañana, la casa estaba revuelta: Beth con dolor de cabeza, Amy sin encontrar sus cosas, y Jo estrellando sombreros. La señora March, ocupada, pedía silencio, mientras Hanna entraba con los pastelitos calientes que siempre preparaba. Jo, entre risas, llevó a Meg a trabajar, convencida de que podrían ser ángeles al regresar. Ambas habían insistido en trabajar desde que su padre perdió el dinero, y aunque Meg se sentía rica con su pequeño sueldo de institutriz, envidiaba el lujo de la familia King. Jo, en cambio, fue enviada con la tía March como acompañante. No le gustaba, pero aceptó, y, para sorpresa de todos, llegó a entenderse con la anciana. Aunque a veces discutían, Jo sabía encontrar siempre una razón para reír y seguir adelante.', 'Pesar → Tristeza o desánimo por algo que ocurre o termina.\r\nResponsabilidades → Deberes u obligaciones que alguien debe cumplir.\r\nVencida → Agotada o desanimada, sin fuerzas.\r\nInstitutriz → Mujer que enseña o cuida a los niños en una casa particular.\r\nIrascible → Persona que se irrita con facilidad; describe a la tía March en capítulos posteriores.'),
(5, 5, 'Capítulo 5', 'imagenes/Mujercitas/Mujercitas_cap_5.jpg', 'La familia March se enfrenta al final de las vacaciones con resignación y una pizca de humor. Meg suspira por la incomodidad de las bolsas y Jo, fiel a su estilo despreocupado, hace bromas mientras la familia se reorganiza tras la fiesta. En el hogar, cada hermana muestra su carácter: Meg, la más mayor, se preocupa por las apariencias; Jo, rebelde y directa, rechaza sentimentalismos; Beth, callada y soñadora, piensa en su \"Peregrino\"; y Amy, la menor, intenta parecer mayor de lo que es. \r\nLaurie, el vecino nuevo, comienza a formar parte de sus vidas, trayendo consigo simpatía y la promesa de una amistad sincera. Las hermanas debaten sobre cumplidos y sentimientos con la inocencia propia de su edad, y la señora March, siempre sabia, les recuerda que aún deben disfrutar de ser niñas. A través de pequeñas escenas cotidianas, la historia retrata los primeros pasos de las hermanas hacia la madurez, entre juegos, reflexiones y un constante deseo de mejorar. Su hogar, humilde pero lleno de amor, se convierte en un refugio donde los ideales de bondad, esfuerzo y esperanza florecen, incluso ante las dificultades. Como en su libro favorito, el viaje apenas comienza, y cada día es una nueva página en su travesía.\r\n', 'Resignación → Aceptación tranquila de algo que no puede cambiarse.\r\nDespreocupado → Que no se altera ni se preocupa fácilmente.\r\nSentimentalismos → Exceso de emoción o sensibilidad.\r\nRefugio → Lugar donde se encuentra protección o consuelo.\r\nTravesía → Viaje o proceso largo y lleno de experiencias.'),
(1, 6, 'Capítulo 1', 'imagenes/Orgullo y prejuicio/OrgulloYPrejuicio_cap_1.jpg', 'Es una verdad universalmente aceptada que un hombre soltero con fortuna necesita una esposa. Aunque poco se sepa de él, las familias vecinas lo ven como una gran oportunidad para casar a una de sus hijas.\r\nUn día, la Sra. Bennet entró emocionada al salón:\r\n—¿Sabías que por fin alquilaron Netherfield Park?\r\nEl Sr. Bennet, tranquilo, respondió que no. Ella contó que un joven rico del norte, el Sr. Bingley, había visitado la casa, quedó encantado y decidió mudarse antes de San Miguel.\r\n—¿Es casado o soltero? —preguntó él.\r\n—¡Soltero! Con cuatro o cinco mil libras al año. ¡Perfecto para nuestras hijas!\r\n—¿Y eso qué tiene que ver con ellas? —replicó él.\r\n—¡Podríamos casarlo con una de ellas! —insistió ella.\r\nCon ironía, él dijo que podían visitarlo solas, o incluso ella, ya que aún era tan guapa como sus hijas.\r\n—¡Qué cosas dices! —protestó—. Una madre con cinco hijas casaderas no piensa en eso.\r\nÉl bromeó que, si no iba, le escribiría a Bingley para ofrecerle casarse con cualquiera, con ligera preferencia por Elizabeth.\r\n—¡No digas eso! —respondió—. Jane es más guapa y Lydia más alegre. Pero tú siempre prefieres a Elizabeth.\r\n—Todas son igual de tontas —dijo él—, pero Elizabeth tiene más juicio.\r\n—No tienes compasión por mis nervios.\r\n—Los respeto mucho —contestó él—. Llevas veinte años hablando de ellos.\r\nAsí era el Sr. Bennet: sarcástico y difícil de entender. Tras 23 años, su esposa aún no lo comprendía. Ella, sencilla y de humor inestable, solo tenía una meta: casar a sus hijas.\r\n', 'Criados: Personas que trabajan en tareas domésticas al servicio de alguien.\r\nJuicio (tener más juicio): Tener buen criterio, sentido común o madurez.\r\nContrariar: Ir en contra de los deseos o ideas de alguien, causar molestia.\r\nIndignada: Molesta o enfadada por algo considerado injusto o insultante.\r\nCompasión: Sentimiento de pena o comprensión por el sufrimiento o molestias de alguien.'),
(2, 6, 'Capítulo 2', 'imagenes/Orgullo y prejuicio/OrgulloYPrejuicio_cap_2.jpg', 'El señor Bennet fue uno de los primeros en visitar al recién llegado señor Bingley, aunque no lo confesó hasta el día siguiente. Como siempre había dicho que no pensaba hacerlo, su familia quedó sorprendida.\r\nLa noticia salió mientras observaba a Isabel adornar su sombrero:\r\n—Espero gustarle al señor Bingley, Isabel —comentó con ironía.\r\n—Eso es imposible, no lo hemos visitado —replicó su esposa, molesta.\r\nIsabel recordó que lo conocieron en un baile, pero la señora Bennet dudó que la señora de Long los presentara, pues tenía sobrinas solteras. El señor Bennet, sarcástico, dijo alegrarse de no depender de ella.\r\nLuego, entre quejas y bromas, hablaron del próximo baile. La señora Bennet lamentó que, si la señora de Long regresaba tarde, no podrían conocer a Bingley. Él le sugirió que fuera ella misma quien lo presentara. Ella protestó, y él, divertido, le respondió que quince días eran poco para conocer a alguien… aunque otros podrían adelantarse. Entonces confesó que ya había hecho la visita.\r\nLas hijas se sorprendieron, y su esposa, tras un momento de asombro, estalló en júbilo:\r\n—¡Sabía que lo harías! ¡Sabía que querías demasiado a tus hijas!\r\nCansado de su entusiasmo, el señor Bennet le dio permiso a Catalina para toser cuanto quisiera y se retiró. La señora Bennet, en cambio, alabó a su marido y aseguró que todo lo hacían por el bien de sus hijas. Predijo incluso que Lydia bailaría con Bingley en el próximo evento.\r\n—¡Eso no me preocupa! —respondió Lydia—. Aunque soy la menor, también soy la más alta.\r\nEl resto de la velada lo pasaron imaginando cuándo devolvería Bingley la visita e iría a cenar con ellos.', 'Confesar → Admitir o declarar algo que se había mantenido oculto.\r\nSarcasmo → Burla irónica o mordaz; humor que ridiculiza sutilmente.\r\nJúbilo → Alegría intensa y desbordante.\r\nReprimenda → Llamado de atención o regaño, implícito en el tono de la Sra. Bennet.\r\nEntusiasmo → Emoción intensa o exaltación al hablar o actuar.\r\n'),
(3, 6, 'Capítulo 3', 'imagenes/Orgullo y prejuicio/OrgulloYPrejuicio_cap_3.jpg', 'El señor Bennet fue de los primeros en visitar al recién llegado señor Bingley, aunque no lo contó hasta el día siguiente. Su esposa y sus hijas lo llenaron de preguntas, pero apenas obtuvieron respuestas. Tuvieron que conformarse con los comentarios de lady Lucas, quien decía que Bingley era joven, guapo, simpático y que asistiría al próximo baile, lo que despertó grandes esperanzas.\r\nDías después, Bingley devolvió la visita. Las hijas no lo conocieron en persona, pero lo vieron desde una ventana: vestía de azul y montaba un caballo negro. Cuando la señora Bennet lo invitó a cenar, él rechazó la oferta por un viaje a Londres, lo que la inquietó, aunque lady Lucas la tranquilizó diciendo que probablemente organizaba el baile. Se rumoraba que traería una gran comitiva, pero finalmente llegó con sus dos hermanas, el esposo de una de ellas y su amigo, el señor Darcy.\r\nEn el baile, Bingley encantó a todos con su amabilidad, bailó con muchas jóvenes —dos veces con Juana Bennet— y prometió otro evento. Darcy, en cambio, fue orgulloso y distante, lo que lo volvió antipático pese a su fortuna.\r\nIsabel Bennet escuchó cuando Bingley intentó convencerlo de bailar. Darcy respondió que ninguna mujer lo interesaba, salvo Juana, y que Isabel era “pasadera, pero no lo bastante hermosa para tentarlo”. Aunque le molestó, ella lo contó luego con humor.\r\nLa velada fue un éxito para las Bennet: Juana fue el centro de atención, María recibió elogios y Catalina y Lydia bailaron sin parar. Al volver a casa, la señora Bennet no dejaba de hablar de Bingley, mientras su esposo, aburrido, pedía calma y expresaba su desprecio por Darcy, al que consideraba arrogante por despreciar a su hija.\r\n', 'Comitiva → Grupo que acompaña a una persona importante en una visita o evento.\r\nArrogante → Persona que actúa con orgullo o superioridad, despreciando a los demás.\r\nDesprecio → Actitud de desdén o falta de valoración hacia alguien.\r\nRumoraba → Se decía o comentaba algo sin confirmar; comunicación informal.\r\nTentarlo → Provocar interés o deseo en alguien; en este caso, atracción romántica.');
INSERT INTO `capitulos` (`id_capitulo`, `id_libro`, `titulo`, `imagen`, `contenido`, `glosario`) VALUES
(4, 6, 'Capítulo 4', 'imagenes/Orgullo y prejuicio/OrgulloYPrejuicio_cap_4.jpg', 'Después del baile, Juana no pudo ocultar su entusiasmo.\r\n —Es justo como debería ser un buen chico —dijo—: sencillo, alegre y encantador.\r\n —Y guapo —añadió Isabel sonriendo—. Lo tiene todo.\r\nJuana confesó que se sintió halagada cuando Bingley la invitó a bailar otra vez.\r\n —No me sorprende —replicó Isabel—. Eres más bonita que cualquiera de las que estaban ahí.\r\nRiendo, Juana cambió de tema y hablaron de las hermanas de Bingley. No le habían causado buena impresión, aunque parecían amables cuando él estaba cerca. Isabel, en cambio, las halló orgullosas y vanidosas, más preocupadas por su posición que por ser cordiales.\r\nBingley había heredado una buena fortuna y pensaba comprar una finca, mientras sus hermanas actuaban en Netherfield como si fueran las dueñas.\r\nA diferencia de su amigo Darcy —reservado y orgulloso—, Bingley era alegre y sociable. Tras el baile, no dejó de pensar en Juana, a quien describió como un ángel.\r\n', 'Vanidosas → Personas que se preocupan en exceso por su apariencia o posición social.\r\nFinca → Propiedad grande en el campo, generalmente con casa y terrenos.\r\nReservado → Que guarda sus pensamientos o sentimientos para sí mismo.\r\nOrgullosas → Personas que se creen superiores a los demás.\r\nHalagada → Que se siente complacida o reconocida por un cumplido o gesto amable.'),
(5, 6, 'Capítulo 5', 'imagenes/Orgullo y prejuicio/OrgulloYPrejuicio_cap_5.jpg', 'Cerca de Longbourn vivía la familia Lucas, muy amiga de los Bennet. Sir Guillermo, antes comerciante, había sido nombrado caballero y se mudó al campo con su familia. Su hija mayor, Carlota, era la mejor amiga de Isabel Bennet: sensata y observadora.\r\nAl día siguiente del baile, los Lucas visitaron a los Bennet para comentar la noche.\r\n —Empezaste bien, Carlota —dijo la señora Bennet—, el señor Bingley te eligió para el primer baile.\r\n —Sí, pero prefirió a Juana —respondió ella.\r\nCarlota contó que Bingley la había llamado “la más bonita del baile”, y la señora Bennet, encantada, fingió modestia. Luego hablaron de Darcy. Isabel comentó que no podía perdonarle su orgullo.\r\n —Podría hacerlo —dijo—, si no hubiese herido el mío.\r\nMaría intervino con calma:\r\n —El orgullo es lo que pensamos de nosotros mismos; la vanidad, lo que queremos que piensen los demás.\r\nLa conversación terminó entre risas, cuando uno de los Lucas bromeó diciendo que, si tuviera la fortuna de Darcy, viviría rodeado de sabuesos y buen vino.\r\n', 'Caballero → Hombre con título de nobleza inferior, o que actúa con cortesía y honor.\r\nSensata → Persona que piensa y actúa con prudencia y buen juicio.\r\nObservadora → Que presta atención a los detalles y se fija en lo que ocurre a su alrededor.\r\nOrgullo → Sentimiento de satisfacción por algo propio; también puede ser arrogancia o exceso de autoestima.\r\nFortuna → En este contexto, significa una gran cantidad de dinero o bienes.\r\n'),
(1, 7, 'Parte 1', 'imagenes/Poesías completas/Poesías_cap_1.jpg', '¡Grande es el mar, espejo de energía,\r\n asombro eterno de la mente humana!\r\n Sus olas chocan con furor constante,\r\n rugiendo al viento con voz soberana.\r\n\r\nParece al mundo entero devorarlo,\r\nse alza, retrocede, vuelve a batallar;\r\ncada embate más fiero que el pasado,\r\ncada golpe más alto en su bramar.\r\n\r\nLa tierra frágil tiembla bajo el ruido,\r\nlas rocas firmes quiebran su carrera;\r\nmas en su furia vuelve renovado,\r\njamás descansa, truena y persevera.\r\n\r\nEl aire vibra lleno de su canto,\r\nsus ecos corren de cerro en montaña;\r\n¿cómo resiste el suelo tan pequeño\r\nsi el mar gigante nunca lo acompaña?', 'Furor constante → Intensidad y violencia continua de las olas en movimiento. | Voz soberana → Metáfora que atribuye autoridad y poder absoluto al mar en su estruendo. | Embate → Golpe violento y repetido de las olas contra la tierra o las rocas. | Bramar → Describe el rugido fuerte del mar o de una fiera; aquí, el estruendo del oleaje. | Persevera → Insistencia o constancia del mar que nunca se detiene en su fuerza.'),
(2, 7, 'Parte 2', 'imagenes/Poesías completas/Poesías_cap_2.jpg', 'Oh soledad serena,\r\ndonde el alma descansa y se serena.\r\nCallan las pasiones, cesa el tormento,\r\nrenace el hombre en noble pensamiento.\r\n\r\nNi el mundo, con sus flores y cuidados,\r\nlogró calmar mis males desgastados;\r\nsolo en tu centro hallé consuelo,\r\npaz verdadera, remedio y cielo.\r\n\r\nAquí se siente al Dios benigno,\r\nsu amor eterno, firme y digno.\r\nQuien busque alivio y desengaño,\r\nhalla en tu abrazo gozo sin daño.\r\n\r\nVenid, amigos, testigos sed,\r\nque en la soledad se halla el bien.', 'Soledad serena → Estado de retiro tranquilo, donde no hay disturbios externos ni internos. | Alma descansa → Imagen de la paz interior y la calma espiritual. | Noble pensamiento → Reflexión elevada que devuelve al hombre su grandeza. | Dios benigno → Imagen de la divinidad compasiva y protectora. | Gozo sin daño → Felicidad pura que no trae consecuencias negativas.'),
(3, 7, 'Parte 3', 'imagenes/Poesías completas/Poesías_cap_3.jpg', 'Oh sueño, dulce alivio,\r\nrefugio del dolor,\r\nen ti mi pena cesa,\r\nrenace mi fervor.\r\n\r\nSi Silvia me desprecia\r\ny mata mi alegría,\r\ntu imagen me consuela\r\ny alivia mi agonía.\r\n\r\nDespierto todo es llanto,\r\ntemor, desdén, olvido;\r\ndormido, en su hermosura\r\nmi gozo está encendido.\r\n\r\nSea real o soñado,\r\nel bien pronto se va;\r\ngocemos, que en el tiempo\r\nlo mismo quedará.', 'Consuelo → El alivio momentáneo que brinda el sueño al corazón herido. | Desvelo → La vigilia, el estado de estar despierto, domina el sufrimiento y la incertidumbre. | Gozo → La felicidad breve que aparece en los sueños, equiparable al gozo real. | Real o soñado → Contraposición central del poema; ambos se conciben como efímeros. | Tiempo → Fuerza inevitable que borra tanto la felicidad soñada como la vivida.'),
(4, 7, 'Parte 4', 'imagenes/Poesías completas/Poesías_cap_4.jpg', 'El alma, entre pesares,\r\n suspira sin consuelo,\r\n aborrece la dicha\r\n y busca oscuro anhelo.\r\n\r\nPrefiere soledad,\r\n rechaza la alegría;\r\n nada logra calmarla,\r\n todo el dolor se enfría.\r\n\r\nLa muerte se presenta\r\ncomo único descanso,\r\npues ningún otro alivio\r\nmitiga su quebranto.', 'Pesares → Tristezas profundas, angustias o congojas que atormentan al alma. | Consuelo → Alivio o esperanza que calma el sufrimiento. | Dicha → Felicidad, gozo o bienestar. | Anhelo → Deseo intenso de algo, en este caso, de la soledad y la calma. | Quebranto → Dolor, sufrimiento o pérdida interior.'),
(5, 7, 'Parte 5', 'imagenes/Poesías completas/Poesías_cap_5.jpg', 'Soy vigía de tristezas,\r\ncargado de amarguras,\r\npaciente como un Fénix\r\nque renace en desventuras.\r\n\r\nCisne que en la agonía\r\ncanta su canto postrero,\r\nsalamandra que en el fuego\r\nhalla sustento sincero.\r\n\r\nOcéano de pesares,\r\ndonde el dolor se derrama,\r\ny las penas, una a una,\r\nse sumergen sin programa.\r\n\r\nSoy la forma de la pena,\r\nun cuerpo hecho de tristeza;\r\nsolo el alivio divino\r\nme sostiene con firmeza.', 'Vigía → Persona que observa con atención; aquí significa alguien siempre atento al dolor. | Amarguras → Sentimientos de tristeza, desdicha o sufrimiento profundo. | Fénix → Ave legendaria que se usa como símbolo de resistencia. | Desventuras → Desgracias o infortunios que llenan de sufrimiento. | Agonía → Dolor extremo o momentos finales antes de la muerte. | Postrero → Último, final; \"canto postrero\" alude al canto final del cisne antes de morir. | Pesares → Tristezas profundas o preocupaciones dolorosas.'),
(1, 8, 'Capítulo 1', 'imagenes/El mago de oz/MagodeOz_cap_1.jpg', 'En las llanuras grises de Kansas vivía Dorothy con sus tíos, Emma y Henry, y su pequeño perro Toto. La casa, una cabaña sencilla y sin color, parecía tan apagada como el cielo y la tierra que la rodeaban. Todo en aquel lugar era monótono, menos Dorothy, cuya alegría y curiosidad rompían la rutina. Toto era su única fuente de juego y consuelo, un destello de vida en medio de tanta quietud.\r\n\r\nUn día, mientras el viento comenzaba a soplar con fuerza, un ciclón se formó en el horizonte. Los tíos corrieron al refugio subterráneo, pero Dorothy, al intentar atrapar a Toto escondido bajo la cama, no alcanzó a salir. Un rugido estremeció la casa, y en un instante, la cabaña fue levantada por el aire, girando entre el polvo y el trueno.\r\n\r\nDorothy, sola con su perro, sintió miedo al principio, pero luego una calma extraña. El mundo giraba a su alrededor como un sueño turbulento. Agotada por el vértigo y la sorpresa, se acurrucó junto a Toto y, mientras la casa seguía flotando en medio del ciclón, cerró los ojos sin imaginar que al despertar, nada volvería a ser igual.', 'Monótono → Que carece de variedad; repetitivo y aburrido. | Ciclón → Tormenta de viento muy fuerte que gira en espiral. | Refugio → Lugar seguro donde se busca protección. | Vértigo → Sensación de mareo o pérdida del equilibrio. | Turbulento → Agitado o violento; con mucho movimiento o confusión.'),
(2, 8, 'Capítulo 2', 'imagenes/El mago de oz/MagodeOz_cap_2.jpg', 'Cuando Dorothy despertó, el silencio reemplazó al rugido del ciclón. Ya no estaba en Kansas. Al abrir la puerta, la luz la cegó un instante: el mundo había cambiado. Frente a ella se extendía un paisaje brillante, lleno de flores, pasto verde y un cielo tan azul que parecía imposible. Todo era color, vida y magia, un contraste absoluto con la monotonía gris que había dejado atrás.\r\n\r\nMientras observaba asombrada, tres pequeños hombres de ropas resplandecientes y sombreros puntiagudos se acercaron, acompañados por una mujer alta vestida de blanco: la Bruja Buena del Norte. Con amabilidad, le explicaron que la casa había caído sobre la Bruja Malvada del Este, la tirana que los había esclavizado. Ahora, al morir aplastada, los Munchkins eran libres, y Dorothy, sin proponérselo, se había convertido en su heroína. Solo quedaban visibles los pies de la bruja, calzados con unos brillantes zapatos plateados.\r\n\r\nLa Bruja Buena le contó que se hallaba en el país de los Munchkins, una parte del vasto reino de Oz, donde en el centro se erguía la Ciudad Esmeralda, hogar del poderoso mago. Dorothy confesó que solo quería volver a Kansas, y la bruja le aconsejó seguir el camino de ladrillos amarillos hasta Oz, quien quizá podría ayudarla. Antes de desaparecer en una ráfaga de luz, hizo que los zapatos mágicos de la bruja muerta se colocaran en los pies de Dorothy. Nadie sabía aún su poder, pero la bruja le advirtió que los conservara. Así, acompañada por Toto y guiada por la promesa de esperanza, Dorothy dio sus primeros pasos por el camino dorado hacia lo desconocido.', 'Contraste → Diferencia marcada entre dos cosas. | Resplandecientes → Que brillan intensamente, reflejando luz o belleza. | Tirana → Persona cruel que domina a otros con abuso de poder. | Heroína → Mujer valiente o destacada por sus acciones nobles. | Ráfaga → Golpe o impulso breve y repentino del viento o de la luz.'),
(3, 8, 'Capítulo 3', 'imagenes/El mago de oz/MagodeOz_cap_3.jpg', 'Con las palabras de la Bruja Buena aún latiendo en su mente, Dorothy tomó a Toto en brazos y echó a andar por el camino de ladrillos amarillos. El sol bañaba los campos, las flores parecían cantar y el aire olía a promesa. Aunque el recuerdo de Kansas le dolía, caminaba con esperanza: el Gran Oz la ayudaría a volver a casa.\r\n\r\nEntre el vaivén del maíz, algo la detuvo. Un espantapájaros colgado de un poste parecía mirarla con tristeza. Para su asombro, le habló con voz temblorosa, pidiéndole que lo bajara. Dorothy lo ayudó, y el espantapájaros, torpe pero agradecido, confesó que no tenía cerebro y soñaba con tener uno. Ella le contó su propósito y él, ilusionado, le pidió acompañarla hasta la Ciudad Esmeralda.\r\n\r\nDorothy aceptó, y pronto descubrió que, pese a su \"falta de cerebro\", su nuevo amigo razonaba con ingenio y ternura. Caminaban entre risas, mientras él tropezaba y ella lo ayudaba a levantarse. Sin notarlo, el espantapájaros ya mostraba la sabiduría que creía no tener. Así, unidos por la amistad y la esperanza, siguieron el camino dorado, sin imaginar que aquella alianza ingenua sería la primera chispa de una aventura inolvidable.', 'Vaivén → Movimiento de un lado a otro, como el del maíz meciéndose con el viento. | Espantapájaros → Muñeco que se coloca en los campos para alejar aves, aquí humanizado. | Ingenuo → Que actúa con inocencia o sin malicia. | Razonar → Pensar con lógica para llegar a conclusiones. | Alianza → Unión entre personas o grupos con un propósito común.'),
(4, 8, 'Capítulo 4', 'imagenes/El mago de oz/MagodeOz_cap_4.jpg', 'Después de liberar al Espantapájaros, Dorothy siguió su camino de ladrillos amarillos junto a su nuevo amigo y su perro Toto. Pronto, el paisaje colorido dio paso a un bosque oscuro donde los altos árboles bloquean la luz y el aire se volvía frío y denso. Dorothy sintió miedo, pero el Espantapájaros, pese a decir que no tenía cerebro, avanzaba tranquilo y conversaba con serenidad.\r\n\r\nDurante el trayecto, Dorothy habló de su gris y ventoso Kansas, mientras él contó cómo fue criado por un granjero y burlado por los cuervos. Soñaba con tener un cerebro para comprender el mundo. El camino se volvió difícil y, cuando el Espantapájaros quedó atrapado, Dorothy y Toto lo ayudaron a salir. Su ingenio demostró que no necesitaba cerebro para ser astuto.\r\n\r\nEl bosque, lleno de sonidos y criaturas extrañas, los inquietaba, pero nada los atacó. Mientras avanzaban, hablaron del Gran Oz: él dudaba, ella mantenía la fe. Ambos seguían movidos por sus deseos más profundos.\r\n\r\nTras una larga jornada, salieron del bosque y hallaron una cabaña donde pasaron la noche, sin saber que el próximo día encontraron al Hombre de Hojalata.', 'Espantapájaros → Figura con forma humana que se coloca en los campos para ahuyentar a las aves. | Serenidad → Estado de calma y tranquilidad emocional, sin alteración. | Ingenio → Capacidad para resolver problemas con creatividad y rapidez mental. | Astuto → Que demuestra habilidad o inteligencia práctica para enfrentar situaciones. | Inquietaba → Causaba preocupación, miedo o desasosiego.'),
(5, 8, 'Capítulo 5', 'imagenes/El mago de oz/MagodeOz_cap_5.jpg', 'Después de descansar en la pequeña casa del bosque, Dorothy, el Espantapájaros y Toto retomaron su camino al amanecer. El recorrido era tranquilo hasta que escucharon un extraño sonido metálico. Siguiendo el ruido, encontraron a un hombre de hojalata completamente inmóvil, con un hacha en la mano. Estaba oxidado y apenas podía hablar, pero les pidió que lo ayudaran. Dorothy halló una aceitera cercana y, junto al Espantapájaros, engrasó sus articulaciones hasta que el leñador pudo moverse libremente.\r\n\r\nAgradecido, les contó que una malvada bruja del Este lo había maldecido para impedirle casarse con la mujer que amaba. Su hacha encantada lo obligó a cortarse las extremidades, y un herrero las reemplazó por hojalata, hasta que perdió el corazón y, con él, la capacidad de amar. Al enterarse de que Dorothy buscaba al Mago de Oz, decidió acompañarlos para pedir un corazón.\r\n\r\nDurante el viaje, el Leñador de Hojalata mostró gran bondad y sensibilidad, aunque insistía en que no tenía corazón. Cuando se lamentó por aplastar a un insecto, el Espantapájaros señaló que quizá ya poseía aquello que buscaba. Así, los tres continuaron su marcha, unidos por la esperanza de que el Gran Oz pudiera concederles sus deseos.', 'Encantada → Hechizada o afectada por un poder mágico. | Maldecido → Aquel que ha sido objeto de una maldición o daño mágico. | Extremidades → Brazos y piernas del cuerpo humano o partes equivalentes. | Sensibilidad → Capacidad de sentir emociones o conmoverse fácilmente. | Concederles → Otorgar o dar algo solicitado, generalmente como favor o recompensa.'),
(1, 9, 'Parte 1', 'imagenes/Los crímenes de la calle morgan/CrímenesCalleMorgan_cap_1.jpg', 'Encontrándome en París durante la primavera y parte del verano de 18..., conocí allí a Monsieur C. Auguste Dupin. Pertenecía este joven caballero a una excelente, o, mejor dicho, ilustre familia, pero por una serie de adversos sucesos se había quedado reducido a tal pobreza, que sucumbió la energía de su carácter y renunció a sus ambiciones mundanas, lo mismo que a procurar el restablecimiento de su fortuna. Con el beneplácito de sus acreedores, quedó todavía en posesión de un pequeño resto de su patrimonio, y con la renta que este le producía encontró el medio, gracias a una economía rigurosa, de subvenir a las necesidades de su vida, sin preocuparse en absoluto por lo más superfluo. En realidad, su único lujo eran los libros, y en París éstos son fáciles de adquirir.', 'Ilustre → Que tiene esclarecida prosapia o es muy distinguido en ella. / Que es insigne o sobresaliente en algo. | Beneplácito → Aprobación o permiso. | Rigurosa → Muy severa, dura o estricta. | Sucumbir → Ceder o rendirse al peso de una presión, dejarse vencer. | Superfluo → No necesario, que está de más. | Subvenir → Venir en auxilio de alguien o acudir a las necesidades de algo.'),
(2, 9, 'Parte 2', 'imagenes/Los crímenes de la calle morgan/CrímenesCalleMorgan_cap_2.jpg', 'Se hallaba la habitación en violento desorden, rotos los muebles y diseminados en todas direcciones. No quedaba más lecho que la armadura de una cama, cuyas partes habían sido arrancadas y tiradas por el suelo. Sobre una silla se encontró una navaja barbera manchada de sangre. Había en la chimenea dos o tres largos y abundantes mechones de pelo cano, empapados en sangre y que parecían haber sido arrancados de raíz. En el suelo se encontraron cuatro napoleones, un zarcillo adornado con un topacio, tres grandes cucharas de plata, tres cucharillas de metal d Alger y dos sacos conteniendo, aproximadamente, cuatro mil francos en oro. En un rincón se hallaron los cajones de una cómoda abiertos, y, al parecer, saqueados, aunque quedaban en ellos algunas cosas. Se encontró también un cofrecillo de hierro bajo la cama, no bajo su armadura. Se hallaba abierto, y la cerradura contenía aún la llave. En el cofre no se encontraron más que unas cuantas cartas viejas y otros papeles sin importancia.', 'Diseminar → Esparcir cosas, separándolas y extendiéndose. | Topacio → Piedra fina, amarilla, muy dura, compuesta generalmente de sílice, alúmina y flúor. | Zarcillo → Pendiente pequeño, generalmente de adorno. | Saqueado → Robado con violencia, especialmente en un lugar tras destrozarlo.'),
(3, 9, 'Parte 3', 'imagenes/Los crímenes de la calle morgan/CrímenesCalleMorgan_cap_3.jpg', '—Mucho me temo —me replicó— que la Gazette no haya logrado penetrar en el insólito horror del asunto. Pero dejemos las necias opiniones de este papelucho. Yo creo que si este misterio se ha considerado como insoluble, por la misma razón debería de ser fácil de resolver, y me refiero al otro carácter de sus circunstancias. La policía se ha confundido por la ausencia aparente de motivos que justifiquen, no el crimen, sino la atrocidad con que ha sido cometido. Asimismo, les confunde la aparente imposibilidad de conciliar las voces que disputaban con la circunstancia de no haber hallado arriba sino a Mademoiselle L Espanaye, asesinada, y no encontrar la forma de que nadie saliera del piso sin ser visto por las personas que subían por las escaleras. El extraño desorden de la habitación; el cadáver metido con la cabeza hacia abajo en la chimenea; la mutilación espantosa del cuerpo de la anciana, todas estas consideraciones, con las ya descritas y otras no dignas de mención, han sido suficientes para paralizar sus facultades, haciendo que fracasara por completo la tan cacareada perspicacia de los agentes del gobierno. Han caído en el grande aunque común error de confundir lo insólito con lo abstruso. Pero precisamente por estas desviaciones de lo normal es por donde ha de hallar la razón su camino en la investigación de la verdad, en el caso de que ese hallazgo sea posible. En investigaciones como la que estamos realizando ahora, no hemos de preguntarnos tanto «qué ha ocurrido» como «qué ha ocurrido que no había ocurrido jamás hasta ahora». Realmente la sencillez con que yo he de llegar o he llegado ya a la solución de este misterio, se halla en razón directa con su aparente falta de solución en el criterio de la policía.', 'Insoluble → Que no puede resolverse o solucionarse. | Perspicacia → Agudeza y rapidez mental para comprender o interpretar algo. | Abstruso → De difícil comprensión.'),
(4, 9, 'Parte 4', 'morgue4.jpg', 'Dupin descubre que el asesino es un orangután fugitivo.', 'Orangután: simio.\nDeducción: razonamiento lógico.\nMisterio: suceso extraño.'),
(5, 9, 'Parte 5', 'morgue5.jpg', 'El caso se resuelve y se reconoce la genialidad de Dupin.', 'Reconocimiento: valoración.\nAnálisis: estudio detallado.\nRazonamiento: pensar lógico.'),
(1, 10, 'Capítulo 1', 'imagenes/Cuentos y leyendas americanas\r\n/CuentosLeyendasAmer_cuento_1.jpg', '—¿Saben por qué el sapo tiene la espalda llena de bultos y manchas? Todo empezó cuando lo invitaron a una fiesta en el cielo de los animales. Vanidoso y fanfarrón, el sapo aseguró que iría por su gran voz. Pero como no podía volar, se escondió dentro de la guitarra del urubú, que lo cargó sin saberlo.\r\n\r\nAl llegar al cielo, el urubú se burló del sapo, pero este apareció triunfante ante todos, causando risas y aplausos. En la fiesta, los animales cantaban y tocaban instrumentos. El sapo, feliz, cantaba con fuerza, aunque en el fondo temía no poder volver. Así que se metió otra vez en la guitarra.\r\n\r\nEl urubú, rencoroso por la burla, lo descubrió en el viaje de regreso. Furioso, sacudió la guitarra hasta que el sapo salió volando por los aires. Mientras caía, el sapo rogaba caer en agua o pasto, pero terminó estrellándose en un patio lleno de piedras.\r\n\r\nQuedó maltrecho, con el cuerpo manchado y lleno de protuberancias. Desde entonces, así luce el sapo, y dicen que también perdió su voz… aunque eso nadie lo puede confirmar.', 'Trapacerías → Describe con precisión la astucia engañosa del sapo para colarse en el cielo. | Urubú → Palabra específica y regional; su significado cultural (ave carroñera) refuerza la venganza del personaje. | Acurrucado → Evoca la postura física del sapo dentro de la guitarra, asociada a miedo o astucia. | Volteretas → Representa la violencia y el movimiento de su caída, dando dinamismo visual al relato. | Maltrecho → Marca el castigo físico del sapo y el origen simbólico de sus manchas.'),
(2, 10, 'Capítulo 2', 'imagenes/Cuentos y leyendas americanas\r\n/CuentosLeyendasAmer_cuento_2.jpg', 'El tigre negro, fuerte y temido, y el venado blanco, frágil y temeroso, eligieron sin saberlo el mismo lugar junto al río para construir su casa. Uno tras otro trabajaron creyendo que Tupa, el dios de la selva, los ayudaba. Cuando la casa estuvo terminada y ambos se encontraron, decidieron convivir y turnarse para conseguir comida.\r\n\r\nEl tigre salió primero y trajo un venado rojo. Su compañero, horrorizado, cocinó la carne sin probarla y pasó la noche en vela, temiendo ser la siguiente presa. Al día siguiente, el venado ideó un plan: engañó al oso hormiguero para que matara a un tigre dormido más grande. Luego llevó el cadáver ante su compañero, diciendo con frialdad:\r\n—Toma, eso encontré.\r\n\r\nEl tigre negro, receloso, no comió. Ambos pasaron la noche en desvelo, temiendo el ataque del otro. Al amanecer, un golpe contra la pared asustó al tigre, que huyó creyendo que el venado lo atacaría. El venado, oyendo las garras, huyó también.\r\n\r\nY así, la casa quedó sola, abandonada por el miedo mutuo.', 'Tupa → En la mitología guaraní, es el dios supremo, creador del mundo y protector de la selva y sus seres. | Herbazal → Terreno cubierto de hierbas silvestres. En el relato, el venado lo desbroza para comenzar la construcción. | Techó → Del verbo techar, que significa cubrir una construcción con un techo. | Forzudo → Que tiene mucha fuerza física. Se refiere al oso hormiguero como animal de gran poder, en contraste con su apariencia inofensiva. | Recelo → Sospecha o desconfianza hacia alguien. El tigre lo siente tras ver al otro tigre muerto.'),
(3, 10, 'Capítulo 3', 'imagenes/Cuentos y leyendas americanas\r\n/CuentosLeyendasAmer_cuento_3.jpg', 'Cuenta una antigua leyenda azteca que Copil, hijo de Malinalxochitl, emprendió un viaje para vengar a su madre, abandonada por el dios Huitzilopochtli. Atravesó montañas, bosques y llanuras sin descanso, iluminado por el sol, la luna y las luciérnagas del trópico. Al llegar a las tierras mexihka, donde crecía el maíz dorado, proclamó su deseo de destruir al cruel dios de la guerra. Al encontrarlo en Chapultepec, Copil regresó a Malinalco por refuerzos y volvió con mil guerreros. Pero su fervor lo delató, y Huitzilopochtli, enfurecido, envió sacerdotes en lugar de soldados. Al caer la noche, estos cruzaron en silencio el lago Texcoco, y mientras el campamento dormía, se acercaron al joven líder y le arrancaron el corazón sin despertar a nadie.\r\n\r\nAl amanecer, sus guerreros hallaron el cuerpo sin vida. El corazón fue ofrecido al dios, quien ordenó enterrarlo entre las rocas del lago. Al día siguiente, del lugar brotó una planta nueva: un nopal, fuerte, espinoso y florido. Desde entonces, el nopal simboliza el valor de Copil y florece en todo el continente. Pero es en México, donde el águila devorando la serpiente, posada sobre él, recuerda el sacrificio del joven guerrero y el origen del pueblo azteca.', 'Chapultepec → Isla en el lago Texcoco; hoy es un bosque y sitio histórico en Ciudad de México. | Huitzilopochtli → Dios mexica del sol y la guerra. | Malinalxochitl → Deidad o figura mitológica hermana de Huitzilopochtli. | Malinalco → Lugar fundado, según la leyenda, por Malinalxochitl. | Mexihka → Forma original náhuatl para referirse al pueblo mexica (azteca).'),
(4, 10, 'Capítulo 4', 'imagenes/leyendas4.jpg', 'En la costa atlántica de Colombia, las islas de San Bernardo deslumbran por su belleza tropical. La más curiosa es Ceicén, que desde lejos parece un castillo medieval. Cuenta la leyenda que allí naufragó maese Falco, viejo armador español, tras perder su barco en una tormenta. Con restos del velero construyó una choza, sobrevivió con cocos, huevos de tortuga y pesca, y pronto se convirtió en el primer colonizador de la isla.\r\n\r\nUn día, mientras fumaba su pipa bajo los cocoteros, dijo en broma: \"¿Qué sería de Lucifer por aquí?\", y, de inmediato, se le apareció el Diablo. Decidieron dar un paseo en bote, y Falco le propuso un trato: responder tres preguntas o concederle lo que pidiera. En alta mar, el Diablo falló la primera: ¿Por qué los cangrejos caminan hacia atrás? Luego, mareado por el oleaje, regresaron a tierra. Falló también la segunda: ¿Qué fue primero, el huevo o la gallina? Y la tercera lo venció del todo: ¿Quién fue tu abuelo?\r\n\r\nVencido, el Diablo le concedió un castillo, pero solo visible desde lejos. Desde entonces, en Ceicén aparece y desaparece una fortaleza encantada, con música, risas y la leyenda de maese Falco, el astuto marinero que engañó al Diablo.', 'Maese → Tratamiento antiguo de respeto hacia un maestro o artesano, que otorga tono histórico y noble al personaje. | Armador → Persona que equipa o financia un barco; revela el origen marítimo y oficio de Falco. | Naufragó → Hundirse o perderse una embarcación en el mar; símbolo del inicio del mito y la soledad del protagonista. | Lucifer → Nombre asociado al Diablo; en el relato, representa la tentación y el desafío sobrenatural. | Fortaleza → Construcción defensiva, aquí usada en sentido mágico, como símbolo del triunfo del ingenio humano sobre lo infernal.'),
(5, 10, 'Capítulo 5', 'imagenes/Cuentos y leyendas americanas\r\n/CuentosLeyendasAmer_cuento_5.jpg', 'Un día, la raposa encontró al jaguar atrapado en un hueco y lo ayudó a salir. Pero él, hambriento, quiso comérsela. Ella propuso consultar al hombre sabio, quien engañó al jaguar para volverlo a encerrar y enseñarle que un bien se paga con otro bien. Desde entonces, el jaguar no dejó de perseguirla. Intentó atraparla con trampas y emboscadas, pero la raposa siempre lo engañaba con su astucia. Fingió estar muerta para burlarse del hombre, se disfrazó con hojas pegadas con miel para beber agua sin ser reconocida y luego, usando resina, se convirtió en el \"animal hoja-seca\", logrando engañar al jaguar durante todo el verano.\r\n\r\nCuando volvieron las lluvias, la raposa se limpió y el jaguar, furioso, volvió a perseguirla sin éxito. Él era fuerte, pero ella tenía oído fino, vista aguda y olfato despierto, por lo que siempre lo descubría. Desesperado, el jaguar fingió estar muerto para atraerla. Los animales lo creyeron, pero la raposa, sospechosa, preguntó si ya había estornudado. El jaguar, sin pensar, lo hizo tres veces. Ella se rió y huyó. Desde entonces, el jaguar no ha logrado atraparla. Porque aunque él es fuerza, ella es ingenio, y eso siempre la ha salvado.', 'Emboscada → Ataque o trampa preparada con sigilo; muestra el carácter depredador del jaguar. | Astucia → Habilidad para engañar o resolver con inteligencia; rasgo esencial de la raposa. | Resina → Sustancia natural pegajosa, usada por la raposa para crear su disfraz; refleja ingenio práctico. | Ingenio → Capacidad de pensar creativamente para sobrevivir; símbolo del triunfo de la inteligencia sobre la fuerza. | Desesperado → Estado de angustia sin control; describe la impotencia del jaguar ante la superioridad mental de la raposa.'),
(1, 11, 'La caída por la madriguera', 'imagenes/Alicia en el país de las maravillas/Alicia_cap_1.jpg', 'La madriguera seguía en línea recta como un túnel durante un trecho, y luego se sumergía repentinamente hacia abajo, tan repentinamente que Alicia no tuvo ni un momento para pensar en detenerse antes de encontrarse cayendo por lo que parecía ser un pozo muy profundo. O el pozo era muy profundo, o ella cayó muy lentamente, porque tuvo mucho tiempo mientras bajaba para mirar a su alrededor y preguntarse qué iba a pasar a continuación. Primero trató de mirar hacia abajo y ver a qué venía, pero estaba demasiado oscuro para ver nada; luego miró a los lados del pozo y se dio cuenta de que estaban llenos de armarios y estanterías: aquí y allá vio mapas y cuadros colgados en pinzas. Al pasar cogió un tarro de uno de los estantes con la etiqueta \"MERMELADA DE NARANJA\", pero, para su gran decepción, estaba vacío: no quería dejar caer el tarro por miedo a matar a alguien que estuviera debajo, así que se las arregló para meterlo en uno de los armarios al pasar.', 'Madriguera → Túnel o agujero donde viven o se esconden algunos animales, como los conejos. | Repentinamente → De forma rápida, inesperada o sin previo aviso. | Sumergía → Se hundía o descendía hacia abajo, como algo que se mete en el agua o la tierra. | Decepción → Tristeza o desilusión al no cumplirse lo que se esperaba. | Estanterías → Muebles con varios niveles (estantes) donde se colocan objetos como libros o frascos.'),
(2, 11, 'El charco de lágrimas', 'imagenes/Alicia en el país de las maravillas/Alicia_cap_2.jpg', 'Al pronunciar estas palabras, su pie resbaló y, en otro momento, ¡splash! estaba metida en el agua salada hasta la barbilla. Su primera idea fue que había caído al mar de alguna manera, \"y en ese caso puedo volver en tren\", se dijo. (Alicia había estado una vez en su vida a la orilla del mar, y había llegado a la conclusión general de que en cualquier lugar de la costa inglesa se encuentran varias máquinas de baño en el mar, algunos niños cavando en la arena con palas de madera, luego una hilera de casas de alojamiento, y detrás de ellas una estación de ferrocarril). Sin embargo, pronto se dio cuenta de que estaba en el charco de lágrimas que había llorado cuando tenía nueve pies de altura.\r\n\r\n\"¡Ojalá no hubiera llorado tanto!\", dijo Alicia, mientras nadaba tratando de encontrar la salida. \"Supongo que ahora me castigarán por ello, ahogándome en mis propias lágrimas. Eso sería algo extraño, sin duda. Sin embargo, todo es extraño hoy\".', 'Barbilla → Parte baja del rostro, situada debajo de la boca. | Ahogándome → Dejar de respirar por estar sumergido en agua o en otro líquido. | Ferrocarril → Medio de transporte formado por trenes que circulan sobre rieles. | Conclusión → Resultado o idea final a la que se llega después de pensar o analizar algo. | Extraño → Que es raro, inusual o diferente de lo común.'),
(3, 11, 'La carrera de caucus', 'imagenes/Alicia en el país de las maravillas/Alicia_cap_3.jpg', '\"¿Qué es un Caucus-race?\" dijo Alicia; no es que quisiera saber mucho, pero el Dodo había hecho una pausa como si pensara que alguien debía hablar, y nadie más parecía dispuesto a decir nada.\r\n\r\n\"Pues\", dijo el Dodo, \"la mejor manera de explicarlo es haciéndolo\". (Y como tal vez quieras probar la cosa tú mismo, algún día de invierno, te diré cómo lo consiguió el Dodo).\r\n\r\nEn primer lugar, se marcó un recorrido de carrera, en una especie de círculo (\'la forma exacta no importa\', decía) y luego se colocó a todo el grupo a lo largo del recorrido, aquí y allá. No había un \'uno, dos, tres y fuera\', sino que empezaban a correr cuando querían y lo dejaban cuando querían, de modo que no era fácil saber cuándo había terminado la carrera.\r\n\r\nSin embargo, cuando llevaban más o menos media hora corriendo, y estaban de nuevo bastante secos, el Dodo gritó de repente: \'¡La carrera ha terminado!\' y todos se agolparon a su alrededor, jadeando, y preguntando: \'¿Pero quién ha ganado?\'\r\n\r\nAl final el Dodo dijo: \'Todos han ganado, y todos deben tener premio\'.', 'Recorrido → Camino o trayecto que se sigue durante una carrera o desplazamiento. | Círculo → Línea curva cerrada donde todos los puntos están a la misma distancia del centro. | Dodo → Ave extinta que se menciona en el cuento; aquí actúa como personaje parlante. | Premio → Recompensa que se da a alguien por haber ganado o destacado en algo. | Secos → En el contexto, se refiere a que los personajes ya no estaban mojados tras correr.'),
(4, 11, 'Atrapada en la casa', 'imagenes/Alicia en el país de las maravillas/Alicia_cap_4.jpg', 'Por suerte para Alicia, la botellita mágica había surtido todo su efecto, y no aumentó de tamaño: aun así era muy incómodo, y como no parecía haber ninguna posibilidad de salir de la habitación, no es de extrañar que se sintiera desgraciada.\r\n\r\n\'Era mucho más agradable estar en casa\', pensó la pobre Alicia, \'cuando uno no estaba siempre creciendo y empequeñeciendo, y siendo mandado por ratones y conejos. Casi desearía no haberme bajado a esa madriguera, y sin embargo, es bastante curiosa esta clase de vida. Me pregunto qué puede haberme pasado. Cuando leía cuentos de hadas, creía que ese tipo de cosas nunca ocurrían, ¡y ahora estoy en medio de uno! ¡Debería haber un libro escrito sobre mí, eso debería! Y cuando crezca, escribiré uno; pero ya soy mayor\', añadió en tono apenado, \'al menos aquí ya no hay lugar para crecer\'.', 'Efecto → Resultado o consecuencia que produce una acción o algo que sucede. | Empequeñeciendo → Haciéndose más pequeño o reduciéndose de tamaño. | Mandado → Obligado o controlado por otra persona o ser (en este caso, por ratones y conejos). | Curiosa → Que tiene interés o deseo de conocer cosas nuevas o extrañas. | Apenado → Que muestra tristeza o pena en su expresión o tono de voz.'),
(5, 11, 'Conversación con la Oruga', 'imagenes/Alicia en el país de las maravillas/Alicia_cap_5.jpg', '\"¿Quién eres tú?\" dijo la oruga.\r\n\r\nEsta no era una apertura alentadora para una conversación. Alicia contestó, más bien tímidamente:\r\n\r\n\"Apenas lo sé, señor, en este momento; al menos sé quién era cuando me levanté esta mañana, pero creo que debo haber cambiado varias veces desde entonces\".\r\n\r\n\"¿Qué quieres decir con eso?\", dijo la Oruga con severidad. \"¡Explícate!\"\r\n\r\n\"Me temo que no puedo explicarme, señor\", dijo Alicia, \"porque no soy yo misma, ya ve\".\r\n\r\n\"No veo\", dijo la Oruga.\r\n\r\n\"Me temo que no puedo decirlo con más claridad\", contestó Alicia muy amablemente, \"porque para empezar yo misma no puedo entenderlo; y el hecho de tener tantos tamaños diferentes en un día es muy confuso\".\r\n\r\n\"No lo es\", dijo la Oruga.\r\n\r\n\"Bueno, tal vez no lo hayas encontrado todavía\", dijo Alicia; \"pero cuando tengas que convertirte en crisálida —algún día lo harás, ya sabes— y después en mariposa, creo que lo sentirás un poco raro, ¿no?\".\r\n\r\n\"Ni un poco\", dijo la Oruga.\r\n\r\n\"Bueno, tal vez tus sentimientos sean diferentes\", dijo Alicia; \"lo único que sé es que a mí me parecería muy raro\".\r\n\r\n\"¡Tú!\", dijo la Oruga despectivamente. \"¿Quién eres tú?\"\r\n\r\nLo que les llevó de nuevo al principio de la conversación. Alicia se sintió un poco irritada por el hecho de que la Oruga hiciera comentarios tan cortos, y se recompuso y dijo, muy seriamente, \"Creo que deberías decirme quién eres, primero\".', 'Apertura → Inicio o comienzo de algo, en este caso, de una conversación. | Tímidamente → De manera insegura o con poca confianza. | Severidad → Forma dura o estricta de hablar o comportarse. | Confuso → Que causa desorden o dificultad para entender. | Irritada → Molesta o enojada por algo que causa fastidio.'),
(1, 12, 'Don Dimas de la Tijereta', 'imagenes/Cien tradiciones peruanas/CienTradiciones_cap_1.jpg', 'En los portales de Lima del siglo XVIII trabajaba don Dimas, un escribano famoso por su astucia. Tenía la fama de resolver cualquier pleito con tal destreza que nadie lograba engañarlo. \r\nUn día, apareció un visitante extraño que le propuso un trato arriesgado: debía defenderlo en un juicio, pero el rival no era cualquiera, sino el mismísimo diablo. El demonio, convencido de que su poder lo haría ganar, aceptó fijar la disputa ante los tribunales celestiales. \r\nDon Dimas, con calma y seguridad, redactó un contrato lleno de cláusulas enrevesadas y trampas legales. El diablo, confiado, firmó sin leer demasiado. Cuando llegó la hora de presentar pruebas, descubrió que todas las condiciones jugaban en su contra. Los jueces, divertidos, fallaron a favor de don Dimas, que sonrió satisfecho. La noticia corrió por Lima: un simple escribano había vencido al diablo usando pura picardía criolla. Desde entonces, la gente decía que hasta el demonio debía tener cuidado con un limeño listo y con pluma en la mano.', 'Astucia → Habilidad o inteligencia para engañar o resolver algo con ingenio. | Pleito → Disputa o juicio legal entre dos partes. | Arriesgado → Que implica peligro o posibilidad de perder algo. | Disputa → Discusión o enfrentamiento entre dos personas o grupos. | Picardía → Habilidad ingeniosa, a menudo con un toque de malicia o humor.'),
(2, 12, 'La emplazada', 'imagenes/Cien tradiciones peruanas/CienTradiciones_cap_2.jpg', 'En la Lima colonial abundaban supersticiones y leyendas. Una noche, en una casona antigua, una joven recibió una visita escalofriante: la figura espectral de una mujer vestida de luto. La aparición le anunció que tenía un plazo fijo para morir, y que nada ni nadie podría salvarla si no cumplía ciertas condiciones. \r\nDesde aquel momento, la muchacha vivió con el corazón en un hilo. La familia, aterrada, buscó médicos, confesores y hasta curanderos, pero todos coincidían en que el anuncio era un presagio inevitable. Cada día que pasaba, la tensión crecía, y las horas parecían más cortas. La joven rezaba con fervor, pero la sombra aparecía puntual para recordarle el plazo. \r\nFinalmente, llegada la fecha, la muchacha cayó enferma de forma repentina y murió, como si la profecía hubiera dictado su destino. La tradición quedó grabada en la memoria popular: en Lima nadie quería ser \"emplazado\", porque significaba estar marcado por la muerte. La historia se contaba en las reuniones familiares, recordando que, entre rezos y miedos, la gente vivía pendiente de lo sobrenatural.', 'Emplazada → Persona a la que se le fija un plazo fatal. | Espectral → Figura fantasmal. | Presagio → Señal de lo que va a ocurrir. | Luto → Vestimenta negra por duelo. | Fervor → Intensidad en los sentimientos, especialmente religiosos.'),
(3, 12, 'El alacrán de Fray Gómez', 'imagenes/Cien tradiciones peruanas/CienTradiciones_cap_3.jpg', 'Fray Gómez era un fraile humilde, conocido por su bondad y su fe inquebrantable. Un día se le acercó un hombre desesperado que necesitaba dinero con urgencia para salvar a su familia. Sin saber qué hacer, el fraile miró alrededor y vio un alacrán que trepaba por la pared. Lo tomó con calma, lo colocó sobre un pañuelo y, con una oración, el insecto se transformó en una joya preciosa.\r\nEl hombre, asombrado, pudo empeñarla y obtener lo necesario para salir de apuros. Pasado el tiempo, regresó con gratitud y devolvió la joya, que al volver a las manos del fraile se transformó de nuevo en un simple alacrán que huyó por el suelo. \r\nLa noticia del milagro corrió como pólvora, y desde entonces Fray Gómez fue considerado un hombre santo, capaz de obrar maravillas solo con su fe. La tradición recuerda que el verdadero poder no estaba en la riqueza, sino en la confianza en Dios y en la caridad desinteresada hacia los demás.', 'Fraile → Religioso de una orden. | Empeñar → Dejar un objeto como garantía de un préstamo. | Inquebrantable → Firme, que no se rompe. | Caridad → Ayuda al prójimo. | Pólvora → Material explosivo; aquí usado como expresión de rapidez.'),
(4, 12, 'La camisa de Margarita', 'imagenes/Cien tradiciones peruanas/CienTradiciones_cap_4.jpg', 'En Lima vivía Margarita, una joven tan bella que era el orgullo de su familia. Se enamoró de un muchacho pobre, y ambos soñaban con casarse. Sin embargo, el padre de ella se opuso con firmeza, convencido de que su hija merecía un partido rico. Tras muchas súplicas, finalmente aceptó, pero puso una condición: la dote debía limitarse a una simple camisa.\r\nEl novio aceptó con humildad, aunque pronto descubriría que aquella \"camisa\" no era nada común. El padre, sin romper su palabra, encargó una prenda bordada con hilos de oro y piedras preciosas, tan lujosa que valía más que todas las joyas de Lima juntas. El día de la boda, \r\nMargarita lució la camisa resplandeciente, y todos comprendieron que la astucia de un padre criollo podía cumplir con la letra de un acuerdo, pero al mismo tiempo burlar su espíritu. La tradición se volvió famosa por su ingenio y su humor, recordando que en el Perú siempre ha existido una forma criolla de dar la vuelta a las reglas.', 'Dote → Bienes que aporta la mujer al casarse. | Bordado → Tejido decorado con hilos. | Criollo → Propio de América, nacido en el virreinato. | Resplandeciente → Que brilla intensamente. | Partido → Persona considerada para matrimonio.'),
(5, 12, 'El Nazareno', 'imagenes/Cien tradiciones peruanas/CienTradiciones_cap_5.jpg', 'Entre las calles de Lima se alzaba la imagen del Señor de los Milagros, también llamado el Nazareno. Cada año, multitudes salían en procesión para rendirle homenaje. El relato cuenta cómo la fe popular era tan fuerte que, en tiempos de peste o temblores, las familias encontraban consuelo bajo el manto morado del Cristo. \r\nLos comerciantes cerraban sus tiendas, las campanas repicaban y las calles se teñían de incienso y flores. La tradición recuerda a un devoto que, al pedir ayuda en un momento de desesperación, juró acompañar la procesión descalzo si obtenía el milagro. Y así ocurrió: su plegaria fue escuchada. \r\nDesde entonces, su ejemplo inspiró a muchos a cumplir promesas similares. El Nazareno se convirtió en símbolo de unidad, esperanza y resistencia para un pueblo que, en medio de dificultades, encontraba fuerza en la fe. Más que una imagen, era el corazón espiritual de Lima, recordando que lo sagrado estaba presente en la vida cotidiana de cada peruano.', 'Nazareno → Imagen de Cristo cargando la cruz. | Procesión → Desfile religioso. | Devoto → Persona muy creyente. | Plegaria → Oración fervorosa. | Incienso → Resina aromática que se quema en ceremonias religiosas.'),
(1, 13, 'El regreso de Roberto', 'imagenes/El caballero carmelo/CaballeroCarmelo_cap_1.jpg', 'Aquel día de sol claro, el silencio del hogar se rompió con el sonido de un caballo que se acercaba desde la plazoleta. Era Roberto, el hermano mayor, que volvía tras largos años de ausencia. Su figura, polvorienta y serena, trajo un torbellino de alegría a la casa. Mi madre, entre lágrimas y sonrisas, lo abrazó con ternura, reconociendo en él los rastros del tiempo y de la distancia. Roberto recorrió cada rincón del hogar con una mezcla de nostalgia y orgullo, hasta que preguntó por la higuerilla que él mismo había sembrado antes de partir. La encontró crecida, fuerte, moviéndose con la brisa marina como si lo saludara. \r\nSobre la mesa, su alforja rebosaba de regalos: dulces, bizcochuelos, tejas y recuerdos de su viaje. Pero el obsequio más especial no era para ninguno de nosotros, sino para papá: un gallo majestuoso, de plumas carmelitas y mirada fiera. Al verlo estirar las alas y cantar con fuerza, todos comprendimos que aquel sería un miembro más de la familia. Así llegó el \"Caballero Carmelo\" a nuestro hogar, trayendo consigo la promesa de nuevas historias y el eco vibrante de un pasado que regresaba al calor del amor familiar.', 'Torbellino → Movimiento rápido y agitado; mezcla de emociones que provoca el regreso. | Nostalgia → Sentimiento de tristeza y cariño por algo del pasado. | Alforja → Bolsa de viaje usada para transportar provisiones o pertenencias. | Majestuoso → De gran belleza, elegancia o imponencia. | Carmelitas → Tono marrón rojizo; color de las plumas del gallo.'),
(2, 13, 'El Pelado', 'imagenes/El caballero carmelo/CaballeroCarmelo_cap_2.jpg', 'Las mañanas en Pisco comenzaban con el canto de los gallos y el aroma del pan recién horneado. Nuestra madre, siempre despierta antes del alba, nos preparaba el desayuno mientras el puerto despertaba con el rumor del mar. El \"Carmelo\" se había convertido en el rey del corral: altivo, fuerte y de canto poderoso. Cada día lo observábamos con admiración, mientras los demás animales revoloteaban a su alrededor. \r\nSin embargo, la paz del hogar se quebró cuando \"el Pelado\", un joven gallo pendenciero, causó destrozos en el comedor. Mi padre, molesto, decidió que el domingo lo comeríamos. Mi hermano Anfiloquio, dueño del \"Pelado\", lloró implorando su perdón. Decía que era un gallo noble, digno de cría, y que todos lo despreciaban solo porque había llegado el \"Carmelo\". La discusión se volvió un pequeño juicio doméstico: cada animal fue defendido y justificado, pero el pobre \"Pelado\" no tuvo quien intercediera por él. \r\nCuando mi madre vio las lágrimas de Anfiloquio caer sobre el plato, se conmovió profundamente. Lo besó en la frente y, desafiando la decisión paterna, dijo con voz dulce: \"No llores, no nos lo comeremos\". Así, entre lágrimas y ternura, el amor venció a la severidad del hogar.', 'Pendenciero → Que busca peleas o discusiones con facilidad. | Altivo → Orgulloso o majestuoso; actitud dominante del Carmelo. | Interceder → Hablar o actuar en favor de alguien para ayudarlo o defenderlo. | Conmovió → Provocó una fuerte emoción o ternura. | Severidad → Rigor o dureza en el trato o las decisiones.'),
(3, 13, 'San Andrés de los Pescadores', 'imagenes/El caballero carmelo/CaballeroCarmelo_cap_3.jpg', 'Más allá de la plazuela y del polvo salitroso del camino se extendía San Andrés de los Pescadores, un rincón humilde entre el mar y el desierto. Allí las palmeras se mecían junto a casitas de caña y estera, mientras los hombres tejían redes y las mujeres limpiaban el pescado al sol. Era un lugar donde la vida transcurría sin prisa, entre el rumor de las olas y el olor a sal. Los niños corrían desnudos sobre la arena y las gaviotas, atrevidas, se mezclaban con ellos como parte del paisaje. \r\nTodo era paz y sencillez. Las familias vivían con modestia, sin codicia ni envidia, unidas por la fe y el trabajo. Aquella comunidad, alejada del ruido y del pecado, parecía un vestigio del mundo antiguo, donde la felicidad no dependía de la riqueza, sino de la armonía. Era en ese escenario donde se celebraban las grandes jugadas de gallos, verdaderas fiestas del pueblo. Allí el destino del \"Caballero Carmelo\" habría de decidirse. \r\nAún nadie lo sabía, pero en ese pequeño rincón del litoral peruano se escribiría una historia de honor y sacrificio, donde un simple gallo se convertiría en símbolo de coraje y nobleza.', 'Salitroso → Que contiene sal; ambiente costero árido del camino. | Estera → Tejido hecho de fibras vegetales usado para construir paredes o techos. | Vestigio → Rastro o huella del pasado; comunidad que conserva la pureza antigua. | Litoral → Zona cercana al mar. | Nobleza → Cualidad moral de quien actúa con honor y generosidad.');
INSERT INTO `capitulos` (`id_capitulo`, `id_libro`, `titulo`, `imagen`, `contenido`, `glosario`) VALUES
(4, 13, 'La apuesta', 'imagenes/El caballero carmelo/CaballeroCarmelo_cap_4.jpg', 'El \"Caballero Carmelo\" no era un gallo cualquiera: su porte altivo, su plumaje carmelita y su mirada encendida recordaban a un hidalgo antiguo. Era fuerte, prudente y majestuoso, como un caballero en armadura. Pero un día, la paz del hogar se quebró. Mi padre, provocado por comentarios malintencionados, aceptó una apuesta para enfrentarlo al temido \"Ajiseco\", campeón de San Andrés. La noticia cayó sobre nosotros como un golpe. \r\nTodos temíamos por la vida de \"Carmelo\", nuestro amigo y compañero. Durante días, un hombre lo entrenó con rigor, mientras nosotros solo podíamos observar desde lejos. El 28 de julio, día patrio, mi padre partió al combate con el gallo entre sus brazos. Mi madre, con lágrimas en los ojos, murmuró: \"¡Qué crueldad!\". Mi hermana menor, Jesús, me tomó de la mano y susurró: \"Acompáñalo… cuídalo\". Salí corriendo tras ellos, decidido a no dejar solo al valiente guerrero que había llenado nuestra infancia de alegría. \r\nEl aire olía a presagio y el sol parecía más triste que nunca. No sabíamos aún que aquel día, entre gritos y apuestas, el \"Carmelo\" escribiría la página más gloriosa y más triste de su historia.', 'Altivo → Orgulloso, con porte erguido y arrogante. | Hidalgo → Persona de nobleza menor; evoca un linaje caballeresco antiguo. | Majestuoso → Imponente, que inspira respeto por su grandeza o belleza. | Rigor → Disciplina y exigencia en la preparación. | Presagio → Señal o indicio que anuncia un hecho futuro, generalmente ominoso.'),
(5, 13, 'El combate', 'imagenes/El caballero carmelo/CaballeroCarmelo_cap_5.jpg', 'San Andrés amaneció de fiesta aquel 28 de julio. Entre banderas peruanas y el bullicio del pueblo, la cancha de gallos se convirtió en el escenario de una batalla de honor. Tras los primeros combates, todos esperaban con ansia el encuentro más esperado: \"¡El Ajiseco y el Carmelo!\". Cuando soltaron a los dos gallos, el contraste era evidente: el Ajiseco, joven y arrogante; el Carmelo, viejo y sereno, con la dignidad de quien ha vivido mucho. Al principio, la lucha fue cruel. Carmelo sangraba, pero resistía. \r\nLas apuestas lo daban por perdido, y mi corazón temblaba con cada golpe. Entonces, en un arranque de fuerza y orgullo, el viejo gallo recordó su linaje y se lanzó con furia. Un silencio profundo precedió al grito del juez: \"¡Todavía no ha enterrado el pico!\". El Carmelo, herido y exhausto, se incorporó una última vez. Con una estocada firme y precisa, derribó al Ajiseco. El público estalló en vítores: \"¡Viva el Carmelo!\". \r\nMi padre lo abrazó emocionado. Había ganado la gloria, pero también había entregado su vida en el combate. Así fue como el héroe del corral se convirtió en leyenda.', 'Bullicio → Ruido alegre y confuso producido por muchas personas o actividades. | Contraste → Diferencia notable entre dos cosas que se comparan. | Linaje → Ascendencia o familia de la que proviene, especialmente noble o distinguida. | Estocada → Golpe dado con una espada; aquí, metáfora del ataque final del gallo. | Vítores → Gritos de entusiasmo y admiración hacia alguien o algo.'),
(1, 14, 'El despertar', 'imagenes/La metamorfosis/Metamorfosis_cap_1.jpg', 'Al despertar una mañana tras sueños intranquilos, Gregorio Samsa se encontró en su cama convertido en un monstruoso insecto. Estaba recostado sobre su espalda dura como un caparazón y, al levantar la cabeza, vio su vientre abombado y marrón, dividido en secciones arqueadas, cubierto por patas flacas y agitadas sin control. Intentó levantarse, pero su cuerpo nuevo no respondía a su voluntad. Pensó en el tren que perdería, en el enojo del jefe, y en cómo explicar su retraso sin levantar sospechas.', 'Intranquilos → Perturbadores, que generan ansiedad. | Monstruoso → De forma aterradora, fuera de lo normal. | Abombado → Hinchado o redondeado hacia fuera. | Agitadas → En movimiento constante y nervioso. | Voluntad → Deseo o intención consciente de hacer algo.'),
(2, 14, 'El encierro', 'imagenes/La metamorfosis/Metamorfosis_cap_2.jpg', 'Gregorio logró abrir la puerta de su habitación arrastrándose con gran esfuerzo. Al verlo, su familia reaccionó con horror. Su madre se desmayó, su padre lo empujó hacia adentro con violencia y Grete, llorando, cerró la puerta. Desde ese momento, Gregorio quedó confinado. Los días pasaban entre el silencio, la penumbra y los restos de comida que su hermana le dejaba. La incomunicación se convirtió en su nuevo lenguaje.', 'Horror → Miedo profundo y repulsión. | Confinado → Obligado a permanecer encerrado. | Penumbra → Luz tenue, entre la oscuridad y la claridad. | Incomunicación → Falta de diálogo o entendimiento.'),
(3, 14, 'La transformación de la familia', 'imagenes/La metamorfosis/Metamorfosis_cap_3.jpg', 'A medida que pasaban los días, Grete empezó a mostrarse indiferente. Dejó de limpiar la habitación y alimentarlo con cuidado. El padre, antes enfermo y débil, consiguió trabajo como mensajero y volvió a usar uniforme. La madre cosía para ayudar con los gastos. Gregorio se volvió invisible: un ser molesto al que se evitaba mirar. La familia se adapta sin él.', 'Indiferente → Sin emoción o interés. | Invisible → Que está presente pero no se quiere ver. | Adaptar → Cambiar para ajustarse a una nueva situación.'),
(4, 14, 'Los inquilinos', 'imagenes/La metamorfosis/Metamorfosis_cap_4.jpg', 'La familia alquila una parte del departamento a tres hombres serios y exigentes. Gregorio, escondido, escucha sus conversaciones y siente que ya no pertenece a ese hogar. Una noche, mientras Grete toca el violín, Gregorio sale de su habitación, atraído por la música. Quiere acercarse, no como insecto, sino como alguien que aún guarda sensibilidad. Pero su presencia provoca el rechazo total: los inquilinos, asqueados, amenazan con irse sin pagar. Grete rompe en llanto y declara que \"eso\" ya no es Gregorio, que hay que deshacerse de él. Gregorio regresa a su cuarto en silencio.', 'Exigentes → Que piden mucho y son difíciles de satisfacer. | Inquilinos → Personas que pagan por vivir temporalmente en una casa. | Asqueados → Con repulsión o rechazo extremo. | Deshacerse → Eliminar algo que se considera una molestia. | Silencio → Aquí, símbolo del aislamiento y la resignación.'),
(5, 14, 'La muerte de Gregorio', 'imagenes/La metamorfosis/Metamorfosis_cap_5.jpg', 'Gregorio ya no come. Permanece inmóvil en la oscuridad de su cuarto, sintiendo el desprecio latente, el olvido de todos. Su cuerpo está débil, cubierto de polvo y restos de comida podrida. Piensa en su familia y en lo inútil que se ha vuelto. En la madrugada, su corazón deja de latir. La sirvienta lo encuentra muerto y lo descarta como basura. Al enterarse, la familia siente alivio. Salen a pasear, disfrutan el sol y piensan en un futuro mejor. La muerte del hijo no es tragedia, sino liberación.', 'Desprecio → Rechazo profundo, falta de respeto. | Latente → Que está oculto pero se siente o se percibe. | Podrida → En descomposición. | Inútil → Sin función o propósito. | Descartar → Desechar, eliminar lo que ya no sirve. | Liberación → Acción de quitarse un peso o una carga.'),
(1, 15, 'Escándalo en Bohemia', 'imagenes/Las aventuras de sherlock holmes/SherlockHolmes_cap_1.jpg', 'Para Sherlock Holmes ella siempre será la mujer. Nunca la he oído nombrar de otro modo. A sus ojos, eclipsa y predomina sobre todo su sexo. No es que sintiera por Irene Adler amor en el sentido ordinario de la palabra. Todos los sentimientos, y aquel entre ellos, parecían repugnantes para su mente fría, precisa, pero admirablemente equilibrada. Sin embargo, para él, siempre fue la mujer. Y sin embargo, el destino quiso que Irene Adler no fuera una mujer común. Ella había conseguido, gracias a su astucia y valentía, adelantarse a los movimientos de Holmes, escapar a su vigilancia y conservar en su poder la fotografía que comprometía al mismísimo Rey de Bohemia. Jamás en su vida Holmes había sufrido un revés semejante, y aunque no lo admitiera con palabras, Watson sabía que, en el fondo, Holmes respetaba profundamente a aquella dama que lo había vencido en su propio terreno: la inteligencia.', 'Eclipsar → Sobresalir o destacar de tal forma que opaca a los demás. | Repugnante → Que causa rechazo o desagrado profundo. | Precisa → Exacta, clara y correcta en los detalles. | Equilibrada → Que mantiene armonía, sin exagerar en un lado u otro. | Astucia → Habilidad para engañar, anticiparse o resolver con ingenio. | Revés → Contratiempo, derrota o fracaso inesperado. | Comprometer → Poner en riesgo la reputación de alguien mediante pruebas o secretos.'),
(2, 15, 'La Liga de los Pelirrojos', 'imagenes/Las aventuras de sherlock holmes/SherlockHolmes_cap_2.jpg', 'El señor Jabez Wilson, un prestamista de cabello rojo brillante, acudió a Holmes para contarle una extraña historia. Había sido contratado por la llamada Liga de los Pelirrojos para copiar, día tras día, párrafos de una enciclopedia, recibiendo un salario sorprendentemente alto por una tarea tan sencilla. Todo parecía marchar bien hasta que, de un día para otro, las oficinas de la Liga cerraron sin dejar explicación. Confundido, Wilson descubrió que había sido víctima de un engaño: mientras él estaba ocupado copiando textos inútiles, su ayudante, que en realidad era un criminal llamado Clay, utilizaba el sótano de su tienda para excavar un túnel hacia un banco cercano con el propósito de robarlo.', 'Prestamista → Persona que se dedica a dar dinero en préstamos a cambio de intereses. | Enciclopedia → Conjunto de libros con información organizada por temas. | Sencilla → Algo fácil de realizar, sin dificultad. | Engaño → Acción que hace creer lo falso para ocultar lo verdadero. | Túnel → Pasaje subterráneo excavado para comunicar un lugar con otro. | Propósito → Objetivo o intención de una acción.'),
(3, 15, 'Un caso de identidad', 'imagenes/Las aventuras de sherlock holmes/SherlockHolmes_cap_3.jpg', 'Mary Sutherland, una joven con una pequeña renta, acudió desesperada a Holmes porque su prometido, Hosmer Angel, había desaparecido el mismo día de su boda. Según su relato, Hosmer siempre había sido misterioso: usaba gafas oscuras, hablaba en voz baja y evitaba ser visto en público. Holmes, tras escuchar con atención, descubrió que Hosmer Angel no existía realmente, sino que era un disfraz utilizado por el padrastro de Mary, el señor Windibank, quien deseaba impedir que la joven se casara para continuar controlando el dinero de su renta. Mary, ingenua y confiada, había sido víctima del engaño de la persona en quien más debía poder confiar.', 'Renta → Ingreso fijo que una persona recibe regularmente. | Desaparecer → Dejar de estar visible o presente sin explicación. | Misterioso → Algo enigmático o difícil de comprender. | Disfraz → Identidad falsa usada para engañar. | Ingenua → Persona que confía con facilidad y no sospecha engaños. | Controlar → Tener dominio o poder sobre las decisiones de alguien.'),
(4, 15, 'El misterio del valle de Boscombe', 'imagenes/Las aventuras de sherlock holmes/SherlockHolmes_cap_4.jpg', 'El joven James McCarthy fue arrestado acusado de asesinar a su propio padre, Charles McCarthy, tras haber sido visto discutiendo con él poco antes de su muerte. Las pruebas parecían irrefutables: testigos, huellas en el barro y la presencia de James en la escena. Sin embargo, Holmes examinó con detalle el terreno, las pisadas y el entorno del valle, y concluyó que James era inocente. El verdadero culpable era John Turner, padre de la mejor amiga de James, quien confesó haber matado a Charles para ocultar un secreto de su turbio pasado criminal. Turner, gravemente enfermo, decidió admitir la verdad antes de morir.', 'Arrestar → Detener legalmente a una persona sospechosa de un crimen. | Irrefutable → Algo que no puede contradecirse con facilidad. | Pisadas → Huellas dejadas por los pies en el suelo. | Inocente → Persona que no cometió el delito del que se le acusa. | Confesar → Admitir públicamente un hecho o un crimen. | Turbio → Algo oscuro, dudoso o relacionado con delitos.'),
(5, 15, 'Las cinco semillas de naranja', 'imagenes/Las aventuras de sherlock holmes/SherlockHolmes_cap_5.jpg', 'John Openshaw acudió a Holmes tras recibir una carta con cinco semillas de naranja y las iniciales K.K.K. Escritas en el papel había amenazas veladas, similares a las que habían recibido antes su padre y su tío, ambos muertos en circunstancias misteriosas después de recibir cartas idénticas. Holmes comprendió que se trataba de una advertencia enviada por el Ku Klux Klan, una organización secreta de origen estadounidense. Aunque Holmes dedujo rápidamente el peligro y aconsejó a Openshaw tomar precauciones, no pudo evitar que, poco después, el joven fuera hallado muerto en un río. El detective, frustrado, reconoció que no siempre llega a tiempo para salvar a quienes confían en él.', 'Amenaza → Aviso o advertencia de un daño futuro. | Velada → Que está oculta o disfrazada, no dicha de manera directa. | Circunstancias → Condiciones o situaciones que rodean un hecho. | Advertencia → Aviso previo para prevenir un peligro. | Secreta → Que no debe saberse públicamente. | Frustración → Sentimiento de impotencia al no poder lograr un objetivo.'),
(1, 16, 'La mano del cementerio', 'imagenes/Mitos y leyendas de arequipa/MitosLeyendasAQP_cap_1.jpg', 'En Arequipa vivía una joven hermosa que maltrataba a su madre. Tras una fuerte pelea, la madre la maldijo y, poco tiempo después, la muchacha murió. Sin embargo, cada cierto tiempo, su mano aparecía sobresaliendo de la tumba hasta que un sacerdote la bendijo y el fenómeno cesó. \r\nAños más tarde, vecinos del cementerio aseguraron ver el espíritu de la joven, vestida de blanco, vagando entre las tumbas. Un DJ que regresaba de trabajar la conoció, la llevó en su moto y hasta le prestó su casaca. Al día siguiente, al buscarla en su casa, la madre le reveló que su hija estaba muerta; al visitar la tumba, hallaron la casaca sobre ella. \r\nEl joven perdió la razón y terminó quitándose la vida, mientras la madre desapareció. Desde entonces, se dice que el fantasma de Mónica sigue apareciendo cerca del cementerio.', 'Fenómeno → Suceso extraño o poco común que puede causar asombro. | Espíritu → Ser inmaterial o alma de una persona que ha muerto. | Vagando → Andar sin rumbo fijo, de un lugar a otro. | Reveló → Dio a conocer algo que estaba oculto o era desconocido. | Razón (perder la razón) → En este contexto, perder la capacidad de pensar o actuar con juicio.'),
(2, 16, 'El diablo de la catedral', 'imagenes/Mitos y leyendas de arequipa/MitosLeyendasAQP_cap_2.jpg', 'Cuando se construía la catedral de Arequipa, los albañiles y arquitectos no lograban levantar uno de los arcos principales: una y otra vez se derrumbaba. Un desconocido apareció ofreciendo terminarlo con la condición de que su rostro fuera tallado en la piedra, junto a los demás canteros. \r\nAceptaron y, sorprendentemente, la obra se sostuvo desde entonces. Más tarde, cuando revisaron las esculturas, descubrieron que el rostro que había quedado grabado en la piedra no era humano, sino el de un ser demoníaco. Desde entonces se cree que el diablo ayudó a levantar aquel arco y que aún permanece allí, vigilando la iglesia.', 'Arco → Estructura curva que sostiene el peso en una construcción. | Cantero → Persona que trabaja la piedra para construir. | Tallado → Esculpido o trabajado en piedra o madera. | Desconocido → Persona cuya identidad no se sabe. | Demoníaco → Relacionado con el diablo o lo maligno.'),
(3, 16, 'El chaco pesca', 'imagenes/Mitos y leyendas de arequipa/MitosLeyendasAQP_cap_3.jpg', 'Durante el gran imperio incaico, se celebraba con gran emoción la festividad del \"Chaco Pesca\", evento que marcaba el inicio de la temporada de pesca. El propio Inca, descendiente del hijo del sol y gobernante del imperio, asistía al valle para presidir la ceremonia. Desde el lugar conocido como Los Pacaysitos, recibía el saludo de los jefes locales y arengaba a los competidores, antes de observar la competencia desde lo alto del cerro El Castillo.\r\nLa prueba comenzaba cuando el Inca levantaba la mano, señal para que los pescadores iniciaran su recorrido. Sobre balsas y con atarrayas, se desplazaban por el río sorteando la corriente mientras pescaban lizas, pejerreyes y camarones. Ganaba quien llegaba primero al punto final y obtenía la mayor pesca.\r\nEl premio para el vencedor era la ñusta más bella y joven de la región, entregada por el mismo Inca como símbolo de honor y fertilidad. Con este acto, se daba por inaugurada la pesca oficial de camarones, recordando a todos respetar la veda. Quienes no obedecían eran expulsados del poblado por desobedecer al Inca y dañar la naturaleza. La festividad culminaba con varios días de danzas, música y banquetes junto al río.', 'Chaco Pesca → Antigua festividad incaica dedicada a la pesca y al agradecimiento a la naturaleza. | Ñusta → Joven mujer noble o princesa del imperio incaico. | Atarraya → Red circular usada para pescar lanzándola al agua. | Veda → Periodo en el que está prohibido pescar o cazar para proteger las especies. | Arenga → Discurso breve que busca animar o motivar a un grupo antes de una acción.'),
(4, 16, 'El puente del diablo', 'imagenes/Mitos y leyendas de arequipa/MitosLeyendasAQP_cap_4.jpg', 'Hace muchos años, en el lugar donde hoy se levanta el Puente Juan Pablo II, entre la avenida Ejército y Cerro Colorado, existía una antigua picantería. Su dueña había contratado a una joven muy hermosa para atraer clientes. Con el tiempo, la muchacha quedó embarazada, y la propietaria, temerosa del qué dirán, le propuso cometer un terrible acto: practicarle un aborto y arrojar el feto al barranco bajo el puente, que aún no tenía nombre.\r\nAños después, aquella joven, ya adulta, caminaba por la zona cuando escuchó el llanto de un bebé proveniente de la torrentera. Conmovida, bajó a recogerlo y lo envolvió con su manta. Pero, mientras lo cargaba, los llantos se transformaron en gruñidos y la criatura comenzó a arañarla con furia. Horrorizada, comprendió que sostenía al mismo demonio y, llena de miedo, lo arrojó nuevamente al vacío del puente.\r\nDesde ese día, la mujer perdió la razón, atormentada por la culpa y el castigo de sus actos. Los vecinos, al conocer la historia, comenzaron a llamar aquel lugar \"El Puente del Diablo\", nombre que conservó durante muchos años, hasta que más tarde fue rebautizado como Puente Juan Pablo II.', 'Picantería → Restaurante tradicional arequipeño donde se sirven platos típicos y picantes. | Torrentera → Quebrada o cauce natural por donde corren aguas de lluvia. | Feto → Ser humano en desarrollo dentro del vientre materno. | Gruñido → Sonido ronco y amenazante que emite una persona o animal.'),
(5, 16, 'El hijo del Misti', 'imagenes/Mitos y leyendas de arequipa/MitosLeyendasAQP_cap_5.jpg', 'Hace mucho tiempo, la tierra dio origen a un nuevo cerro llamado Misticito, hijo del majestuoso volcán Misti. El Misti, feliz por el nacimiento de su descendiente, lanzó cenizas, fuego y lava en señal de alegría. Sin embargo, aquella celebración le hizo perder parte de su forma cónica. Con los años, los sabios temieron que el Misticito creciera demasiado y provocara una gran erupción, causando conflictos entre su padre, el Misti, y su tío, el Chachani.\r\nLos gentiles, antiguos habitantes de las riberas del río Chili, decidieron intervenir. Una noche, del cielo descendieron naves luminosas con pequeños seres que prometieron ayudarles si cumplían una tarea. Los gentiles bajaron al centro de la tierra, trajeron oro y fabricaron una cadena dorada con la que, siguiendo el acuerdo, amarraron al Misticito para impedir su crecimiento.\r\nCumplida la promesa, las naves lanzaron rayos de fuego que abrieron grietas y cortaron las raíces del joven volcán. Miles de años después, un arriero advirtió que el Misticito intentaba liberarse, lanzando fuego por las noches. Entonces, un padre sabio ordenó colocar zunchos de hierro alrededor del cerro, asegurando que jamás crecería tanto como su padre, el Misti.', 'Gentiles → Antiguos pobladores anteriores a los incas, según las leyendas arequipeñas. | Misticito → Cerro considerado el \"hijo\" del volcán Misti. | Zuncho → Cinta o aro metálico que se utiliza para sujetar o reforzar algo. | Arriero → Persona que guía animales de carga, especialmente mulas o burros.'),
(1, 17, 'El palacio de la inocencia', 'imagenes/Un mundo para julius/MundoJulius_cap_1.jpg', 'Julius nació en un palacio de la avenida Salaverry, rodeado de jardines, sirvientes y objetos antiguos que contaban la historia de su familia. Desde pequeño, el lujo formaba parte de su vida, pero también una silenciosa tristeza. Su padre había muerto cuando él apenas aprendía a caminar, y su madre, hermosa y elegante, vivía entre fiestas y ausencias. \r\nJulius encontraba refugio en la servidumbre: en la ternura de Vilma, que lo bañaba con paciencia, y en las historias de Nilda, que le hablaban de selvas y espíritus lejanos. Le fascinaba la carroza del bisabuelo, cubierta de polvo, donde pasaba horas jugando a ser un héroe. Sin embargo, algo en su mirada inocente empezaba a descubrir el dolor: la tristeza de su madre, el cansancio de los criados, los silencios del palacio. \r\nCuando murió Bertha, la nana de su hermana Cinthia, los niños organizaron un pequeño entierro en el huerto. Allí, mientras enterraban una caja con los objetos de la vieja, Julius sintió por primera vez la sombra de la muerte y la fragilidad del amor.', 'Servidumbre → Conjunto de personas que trabajan al servicio de una familia. | Ausencias → Falta o alejamiento de alguien que debería estar presente. | Ternura → Afecto suave y sincero que inspira cariño o compasión. | Fascinaba → Atraía intensamente la atención o el interés. | Fragilidad → Condición de ser débil o fácil de romper, física o emocionalmente.'),
(2, 17, 'Fiestas y apariencias', 'imagenes/Un mundo para julius/MundoJulius_cap_2.jpg', 'Desde la muerte de Bertha, Julius y Cinthia se volvieron inseparables. Los unía un secreto compartido y una ternura silenciosa que crecía entre los pasillos del palacio. Cinthia, delicada y cada vez más pálida, encontraba en su hermano el único refugio posible frente a la indiferencia de su madre, que seguía saliendo de noche, envuelta en perfumes y ausencias. Un día, Susan los envió al cumpleaños de su primo Rafaelito Lastarria. Los vistieron de blanco, impecables, como si la pureza pudiera protegerlos del mundo. \r\nPero apenas llegaron, comprendieron que entraban en territorio enemigo: los primos los recibieron con burlas, con una violencia disfrazada de juegos. Julius, confundido, vio cómo lanzaban terrones, cómo se reían de su hermana mientras ella intentaba mantener la compostura. Todo era brillo, risas forzadas, copas de cristal y niños que aprendían demasiado pronto la crueldad. En medio de ese festejo ajeno, Julius sintió una vergüenza nueva, un deseo de huir de aquella sociedad elegante y vacía que no comprendía su dolor. \r\nDe regreso al palacio, abrazó a Cinthia y notó que respiraba con dificultad. Entonces entendió, sin palabras, que algo en ella se apagaba lentamente, como una vela en medio del lujo, como su propia inocencia perdiéndose en la sombra.', 'Ternura → Sentimiento de cariño profundo y delicado hacia alguien o algo. | Indiferencia → Falta de interés, atención o afecto hacia lo que sucede. | Compostura → Actitud serena y controlada frente a una situación difícil. | Vergüenza → Sentimiento de incomodidad o humillación ante algo que avergüenza o duele. | Inocencia → Estado de pureza y desconocimiento del mal o la malicia.'),
(3, 17, 'Despertares dolorosos', 'imagenes/Un mundo para julius/MundoJulius_cap_3.jpg', 'El tiempo comenzó a pasar y Julius, más curioso que nunca, empezó a notar los cambios en su casa. Su madre seguía saliendo cada noche, envuelta en perfumes y vestidos brillantes, mientras él permanecía solo con los sirvientes que lo adoraban como a un hijo propio. La ausencia de Cinthia, cada vez más enferma, llenaba los pasillos del palacio de un silencio pesado. \r\nJulius buscaba consuelo entre las risas cansadas de Vilma y las historias fantásticas de Nilda, pero algo dentro de él se quebraba poco a poco. Ya no encontraba alegría en los juegos ni en las sombras del jardín. Las conversaciones de los adultos, a medio oír, le revelaban un mundo de secretos, de amores prohibidos y mentiras elegantes. \r\nEn las fiestas, veía a su madre reír como si nada doliera, mientras él observaba desde lejos, sintiendo una distancia que no podía nombrar. En esa mezcla de lujo y tristeza, Julius comenzó a comprender que crecer significaba perder, y que la ternura no siempre sobrevivía en las casas hermosas.', 'Curioso → Que siente un fuerte deseo de saber o conocer. | Ausencia → Falta o carencia de alguien o algo que debería estar presente. | Consuelo → Alivio del dolor o la tristeza. | Elegantes → Refinadas o de buen gusto en el modo de vestir o comportarse. | Ternura → Sentimiento de cariño profundo, suave y sincero.'),
(4, 17, 'El colegio inglés', 'imagenes/Un mundo para julius/MundoJulius_cap_4.jpg', 'Julius empezó a asistir al colegio inglés, un mundo completamente distinto al del palacio. Allí, entre uniformes impecables y reglas estrictas, descubrió la dureza de los niños que no sabían de ternura. Lo miraban con desdén por su acento, por su timidez y por ser \"el niño rico\". Pronto comprendió que el dinero no lo protegía del desprecio ni del aislamiento. En los recreos, mientras los demás jugaban fútbol o gritaban, él prefería observar los árboles del patio y pensar en Vilma, en el olor del jardín, en su hermana Cinthia, cada vez más ausente. \r\nA veces sentía ganas de llorar, pero se contenía, porque los otros se reían de cualquier muestra de tristeza. El colegio le enseñó lo que su casa no: que el mundo podía ser cruel y que la soledad también se aprendía. Al volver, su madre apenas lo escuchaba, ocupada con visitas y compromisos sociales. \r\nEn medio de tanto orden y silencio, Julius empezó a hacerse preguntas que nadie respondía. Así, su infancia fue perdiendo color, como una fotografía que se borraba lentamente con el tiempo.', 'Desdén → Actitud de desprecio o indiferencia hacia alguien. | Timidez → Inseguridad o temor al expresarse frente a otros. | Desprecio → Falta de aprecio o valoración hacia una persona o cosa. | Aislamiento → Estado de estar apartado o separado de los demás. | Soledad → Sensación de estar solo o sin compañía emocional.'),
(5, 17, 'La melancolía del crecimiento', 'imagenes/Un mundo para julius/MundoJulius_cap_5.jpg', 'El tiempo siguió avanzando y Julius comenzó a mirar su casa con otros ojos. El palacio, antes un lugar de juegos y risas, ahora parecía enorme y vacío. Su madre se mostraba cada vez más distante, encerrada en fiestas, amigos nuevos y conversaciones que Julius no entendía. Vilma seguía cuidándolo con amor, aunque ya no podía protegerlo del dolor que crecía dentro de él. \r\nSu hermana Cinthia estaba más débil, y cada visita al hospital llenaba al niño de un miedo que no sabía nombrar. En las noches, Julius recorría los pasillos en silencio, escuchando los ecos de un pasado que se desvanecía. Empezó a sospechar que el mundo de los adultos era frágil y mentiroso, construido sobre apariencias. \r\nLas sonrisas de su madre, los perfumes y los gestos educados ocultaban una tristeza profunda. Julius, sin entender del todo, empezó a mirar más allá de las palabras, descubriendo que la belleza podía esconder la soledad y que el amor, a veces, también dolía.', 'Desvanecía → Se iba borrando o desapareciendo poco a poco. | Apariencias → Aspectos externos que pueden ocultar la verdad. | Frágil → Fácil de romper o dañar, tanto física como emocionalmente. | Educados → De modales corteses y refinados. | Soledad → Estado o sentimiento de estar sin compañía o afecto.'),
(1, 18, 'La apuesta imposible', 'imagenes/La vuelta al mundo en 80 días/VueltaMundo_cap_1.jpg', 'En el solemne y silencioso Reform Club, la vida de Phileas Fogg transcurría con una precisión meticulosa, un ritual impasible donde cada segundo tenía su lugar. Nadie conocía su pasado; solo su presente, una rutina tan predecible como el reloj de la torre. Pero esa tarde, una conversación sobre un audaz robo bancario y las nuevas conexiones de transporte encendió una chispa audaz en sus ojos. Ante el escepticismo de sus colegas, declaró que era posible dar la vuelta al mundo en 80 días. La discusión se convirtió en una apuesta de 20.000 libras. Con su calma flemática de siempre, Fogg aceptó el reto y anunció que partiría esa misma noche, alterando por primera vez el orden perfecto de su existencia.', 'Meticulosa → Extremadamente cuidadosa y precisa en los detalles. | Impasible → Que no muestra ninguna emoción o alteración. | Audaz → Valiente, atrevido, que no teme los riesgos. | Escepticismo → Duda o incredulidad sobre la verdad de algo. | Flemática → Que tiene una calma y compostura inalterables.'),
(2, 18, 'El rescate de Aouda', 'imagenes/La vuelta al mundo en 80 días/VueltaMundo_cap_2.jpg', 'El tren se detuvo abruptamente en medio de la India. Las vías terminaban allí. Para continuar, Fogg compró un elefante. En el camino, se toparon con un séquito que conducía a una joven viuda, Aouda, hacia una pira funeraria para ser sacrificada en un ritual de sutí. El fanatismo de la multitud parecía insuperable. Mientras Sir Francis Cromarty se resignaba a la barbarie, Fogg, imperturbable, decidió que salvarla era un deber, aunque le costara un tiempo precioso. Trazó un plan audaz: esperar la noche. Con una astucia increíble, Passepartout se hizo pasar por el difunto esposo resucitado en medio del humo, tomó a Aouda en brazos y escapó del caos. El rescate fue un éxito, un triunfo de la humanidad sobre la tradición brutal.', 'Séquito → Grupo de personas que acompaña a una figura importante. | Pira funeraria → Hoguera para quemar un cuerpo como parte de un rito. | Fanatismo → Pasión o defensa exagerada y ciega de una creencia. | Imperturbable → Que no se altera ni se inmuta ante las dificultades. | Astucia → Habilidad para engañar o evitar el engaño y lograr un objetivo.'),
(3, 18, 'El ataque de los Sioux', 'imagenes/La vuelta al mundo en 80 días/VueltaMundo_cap_3.jpg', 'El tren cruzaba la vasta planicie americana, un viaje monótono que de repente se vio roto por una estampida de bisontes que detuvo la marcha por horas. Más tarde, el silbido agudo del tren fue ahogado por gritos de guerra. Una banda de indios Sioux atacó el convoy con una furia implacable. Los pasajeros se defendieron como pudieron, y Fogg demostró una destreza militar inesperada. Sin embargo, el tren corría sin control hacia un puente destruido. En un acto intrépido, Passepartout se deslizó bajo los vagones y logró desvincular la locomotora justo a tiempo. El tren se detuvo, pero en la confusión, Passepartout y otros dos pasajeros fueron capturados. Fogg, sin dudarlo, decidió organizar un rescate, sacrificando su itinerario por la lealtad.', 'Planicie → Gran extensión de terreno plano, sin altos ni bajos. | Estampida → Huida impetuosa de un grupo de animales o personas. | Implacable → Que no se puede aplacar o detener; severo y sin piedad. | Intrépido → Que no teme los peligros; valiente. | Desvincular → Separar o soltar algo que estaba unido.'),
(4, 18, 'El arresto en Liverpool', 'imagenes/La vuelta al mundo en 80 días/VueltaMundo_cap_4.jpg', 'Tras una travesía atlántica frenética, Fogg, Aouda y Passepartout pisan suelo inglés en Liverpool. El triunfo parece inminente; solo les quedan unas pocas horas para llegar a Londres y ganar la apuesta. Con la victoria al alcance de la mano, una figura emerge de la niebla: el detective Fix. Con una convicción inquebrantable, pone su mano sobre el hombro de Fogg y lo declara arrestado. Los grilletes se cierran sobre las muñecas del caballero. El mundo de Fogg parece desmoronarse. La ironía es cruel: ha vencido tormentas, cruzado continentes y superado todos los obstáculos, solo para ser detenido en su propio país, a un paso de la meta, por un error de la ley. La desesperación es total.', 'Frenética → Muy rápida, agitada y descontrolada. | Inminente → Que está a punto de suceder. | Convicción → Seguridad total que se tiene sobre algo. | Grilletes → Aros de hierro para sujetar a un prisionero por las muñecas o tobillos. | Desmoronarse → Deshacerse, venirse abajo, perder la entereza. | Ironía → Contradicción burlona entre lo que sucede y lo que se esperaba.'),
(5, 18, 'La victoria inesperada', 'imagenes/La vuelta al mundo en 80 días/VueltaMundo_cap_5.jpg', 'En su casa de Savile Row, reina un silencio de resignación. Liberado de la cárcel, Phileas Fogg cree haber perdido la apuesta por apenas cinco minutos. Su fortuna está perdida, y su futuro es incierto. Aouda, conmovida, le confiesa su amor, ofreciéndole una riqueza que el dinero no puede comprar. Fogg, por primera vez, deja ver una emoción profunda y acepta casarse con ella. Envía a Passepartout a organizar la boda para el día siguiente, que creen que es lunes. Pero su mayordomo regresa en un estado de agitación total. Ha descubierto la revelación final: al viajar constantemente hacia el Este, en dirección al sol, habían ganado un día entero cruzando los meridianos. ¡No era domingo por la noche, sino sábado! Todavía tenían tiempo. La letargia se transforma en una carrera frenética hacia el Reform Club.', 'Resignación → Aceptación con paciencia de una adversidad. | Agitación → Estado de inquietud y nerviosismo extremo. | Revelación → Descubrimiento de algo que era secreto o desconocido. | Meridianos → Líneas imaginarias que van de un polo a otro de la Tierra; cruzarlas afecta la hora local. | Letargia → Estado de adormecimiento o falta de energía. | Frenética → Que se hace con gran rapidez y agitación.');
