INSERT INTO `libros` (`id_libro`, `titulo`, `AUTOR`, `descripcion`, `imagen`, `archivo`, `resumen`, `personajes`, `categoria`, `imagen2`) VALUES
(1, 'La ciudad y los perros', 'Mario Vargas Llosa', 'Un asesinato en un colegio militar amordaza a los cadetes con un código de silencio más férreo que cualquier reglamento. Para descubrir al culpable, deberán traicionar la única lealtad que conocen: la de la manada. ¿Qué vale más, la verdad o la supervivencia?', 'imagenes/laciudadylosperros/CiudadPerros_portada_1.jpg', 'alicia_maravillas.pdf', 'En La ciudad y los perros, un grupo de cadetes del Colegio Militar Leoncio Prado vive entre violencia, humillaciones y secretos oscuros. El “Círculo” trama venganzas, mientras el destino de todos se desmorona. Traición, poder y brutalidad revelan la corrupción de una sociedad entera. ¿Hasta dónde llega la lealtad?', 'El Jaguar – lider del “Circulo”, violento, pero con un codigo de honor.\r\nRicardo Arana “El Esclavo” – timido, victima constante de abusos.\r\nAlberto Fernandez “El Poeta” – narrador en parte, sensible y observador.\r\nEl teniente Gamboa – oficial que busca justicia.\r\nEl Boa – companero brutal y temido.\r\nEl Serrano Cava – complice en robos de examenes\r\nTeresa – interes amoroso del Poeta.\r\nEl coronel – simbolo de la autoridad corrupta.\r\n', 'Drama', 'imagenes/laciudadylosperros/CiudadPerros_portada_2.jpg'),
(2, 'Drácula', 'Bram Stoker', 'Drácula es una novela de terror gótico escrita por el autor irlandés Bram Stoker. La historia sigue ', 'imagenes/Dracula/Dracula_portada_1.jpg', 'Frankenstein.pdf', 'Cuando el joven abogado Jonathan Harker visita el castillo del misterioso conde Dracula, no imagina que desatara una pesadilla que se extendera mas alla de Transilvania. El vampiro viaja a Inglaterra para expandir su dominio, sembrando terror y muerte a su paso. Mientras sus victimas caen bajo su hechizo, un grupo liderado por el sabio Van Helsing emprende una desesperada caza para destruirlo. En esta lucha entre la razon y lo sobrenatural, Dracula revela el rostro eterno del miedo y la sed de poder.', 'Conde Dracula. Un antiguo noble transilvano y vampiro inmortal. Es el antagonista principal de la novela.\r\nJonathan Harker. Joven abogado ingles que viaja al castillo de Dracula en Transilvania al comienzo de la novela.\r\nMina Murray. Prometida (y luego esposa) de Jonathan Harker. Intelectual y muy inteligente.\r\nLucy Westenra. Mejor amiga de Mina. Bella y dulce joven inglesa.\r\nProfesor Abraham Van Helsing. Medico y erudito holandes, experto en enfermedades raras y lo sobrenatural.\r\nDr. John Seward. Director de un manicomio en Inglaterra, antiguo pretendiente de Lucy.\r\nArthur Holmwood (Lord Godalming). Prometido de Lucy, luego se convierte en Lord tras la muerte de su padre.\r\nQuincey P. Morris. Atractivo texano y otro de los pretendientes de Lucy.\r\nRenfield. Paciente del Dr. Seward internado en el manicomio.\r\n', 'Terror gótico', 'imagenes/Dracula/Dracula_portada_2.jpg'),
(3, 'El monstruo de Frankenstein', 'Mary Shelley', 'Frankenstein narra la historia de Victor, quien logra dar vida a un ser construido a partir de resto', 'imagenes/El monstruo de frankenstein/Frankenstein_portada_1.jpg', 'frankenstein.pdf', 'Victor Frankenstein, un joven cientifico obsesionado con vencer a la muerte, logra lo imposible: crear vida a partir de la materia muerta. Sin embargo, horrorizado por su obra, la abandona, desatando una tragedia inevitable. La criatura, inteligente pero condenada al rechazo, busca amor y venganza, convirtiendose en el reflejo mas oscuro de su creador. A traves de esta historia de ciencia, dolor y redencion, Frankenstein revela los limites del conocimiento humano y las consecuencias devastadoras de jugar a ser Dios.', '\r\n    Victor Frankenstein. Es el protagonista de la novela. Un joven científico suizo obsesionado con descubrir los secretos de la vida.\r\nLa criatura (el monstruo de Frankenstein). Ser artificial creado por Victor. Es físicamente imponente y de apariencia grotesca, pero inicialmente es sensible, inteligente y busca afecto.\r\nRobert Walton. Capitán de un barco que explora el Ártico. Es quien narra la historia a través de cartas dirigidas a su hermana.\r\nElizabeth Lavenza. Prima adoptiva y prometida de Victor.\r\nHenry Clerval. Mejor amigo de Victor desde la infancia.\r\nAlphonse Frankenstein. Padre de Victor.\r\nWilliam Frankenstein. Hermano menor de Victor.\r\nJustine Moritz. Criada de la familia Frankenstein, acusada injustamente del asesinato de William.\r\nDe Lacey. Anciano ciego que vive en una cabaña en el bosque.\r\nFelix, Agatha y Safie. Miembros de la familia De Lacey. Sin saberlo, educan a la criatura a través de sus conversaciones y enseñanzas.', 'Terror gótico', 'imagenes/El monstruo de frankenstein/Frankenstein_portada_2.jpg'),
(4, 'Crimen y castigo', 'Fiódor Dostoyevski', 'Un joven asesina a una anciana avara y enfrenta culpa y redención.', 'imagenes/Crimen y castigo/CrimenYCastigo_portada_1.jpg', 'crimen_castigo.pdf', 'Raskólnikov, un joven estudiante inteligente pero desesperado, asesina a una anciana avara convencido de que su crimen está justificado por un ideal superior. Sin embargo, la culpa lo consume y lo arrastra a una lucha interna entre la razón y la conciencia. Mientras la justicia lo acecha, su mente se desmorona en un abismo de miedo, delirio y remordimiento. Solo a través del sufrimiento y del amor puro de Sonia, descubrirá el verdadero significado de la redención y la paz interior.', 'Raskólnikov, Sonia Marmeládova, Dunia, Pulkhéria Raskólnikova, Razumikhin, Porfirio Petróvich, Marmeládov, Svidrigáilov, Lujin, Aliona Ivánovna, Lizaveta Ivánovna', 'Drama', 'imagenes/Crimen y castigo/CrimenYCastigo_portada_2.jpg'),
(5, 'Mujercitas', 'Louisa May Alcott', 'En una época que silencia a las mujeres, cuatro hermanas luchan por seguir sus sueños. Meg, Jo, Beth', 'imagenes/Mujercitas/Mujercitas_portada_1.jpg', 'mujercitas.pdf', 'En una pequeña casa de Nueva Inglaterra, cuatro jovenes forjan su caracter entre desafios cotidianos, anhelos personales y vinculos que se ponen a prueba. Mientras el mundo afuera cambia con violencia, dentro del hogar florecen las dudas, los suenos y las decisiones que marcaran sus destinos.', '\r\nJo March “La Inconforme” - decidida, valiente y con pasión por la escritura. \r\nMeg March “La Mayor” - sensata, maternal y soñadora de una vida tranquila.\r\nBeth March “La bondadosa” - reservada, generosa y amante de la música.\r\nAmy March “La ambiciosa” - refinada, artística y con ansias de reconocimiento.\r\nMarmee – madre firme y amorosa, pilar de la familia.\r\nLaurie – carismática, generosa y cercana a las hermanas.\r\nProfesor Bhaer –  intelectual, amable y figura clave en la vida de Jo.', 'Novela romántica', 'imagenes/Mujercitas/Mujercitas_portada_2.jpg'),
(6, 'Orgullo y Prejuicio', 'Jane Austen', 'Lizzy Bennet no busca amor, pero el orgulloso Sr. Darcy cambiará su destino. Entre prejuicios, escán', 'imagenes/Orgullo y Prejuicio/OrgulloYPrejuicio_portada_1.jpg', 'orgullo_prejuicio.pdf', 'En una sociedad donde el matrimonio lo es todo, Elizabeth Bennet desafia las normas con inteligencia y caracter. Cuando conoce al arrogante Senor. Darcy, nace una tension irresistible. Orgullo, malentendidos y deseos se entrelazan en una historia que demuestra que el amor verdadero no teme al escandalo ni al cambio interior.', 'Elizabeth Bennet: Inteligente y valiente. No se deja llevar por apariencias y defiende lo que cree justo\r\nSr. Darcy: Hombre rico y reservado. Parece orgulloso, pero tiene un gran corazón cuando se le conoce.\r\nSr. Bennet: Padre irónico pero distante. Prefiere observar que intervenir en los problemas familiares.\r\nSra. Bennet: Madre escandalosa. Solo piensa en casar a sus hijas con hombres ricos.\r\nJane Bennet: Hermana mayor, dulce y hermosa. Siempre ve lo bueno en todos.\r\nLydia Bennet: Menor, coqueta e inmadura. Su imprudencia pone en riesgo a la familia.\r\nCharles Bingley: Rico, amable y sociable. Se enamora rápido y con sinceridad.\r\nCharlotte Lucas: Amiga práctica. Se casa por seguridad, no por amor.\r\nSr. Collins: Clérigo ridículo que quiere casarse por compromiso social.\r\nGeorge Wickham: Encantador pero mentiroso. Engaña a todos con su buena apariencia.\r\nLady Catherine: Noble orgullosa y mandona. No acepta que el amor cruce clases sociales.', 'Novela romántica', 'imagenes/Orgullo y Prejuicio/OrgulloYPrejuicio_portada_2.jpg'),
(7, 'Poesías completas', 'Mariano Melgar', 'Obra poetica completa de Mariano Melgar, pionero de la lirica nacional peruana.', 'imagenes/Poesías completas/Poesías_portada_1.jpg', 'poesias_completas.pdf', 'Antología con yaravíes y poemas líricos de Mariano Melgar: temas de amor, patria, desengaño y melancolía, expresados en un tono íntimo y mestizo.', 'Silvia, El Ruiseñor, El Calesero, El Lobo, La Ballena, El Yo Poetico', 'Tradiciones y cuentos', 'imagenes/Poesías completas/Poesías_portada_2.jpg'),
(8, 'El maravilloso mago de Oz', 'L. Frank Baum', 'Dorothy viaja a Oz tras un ciclon y busca volver a Kansas con ayuda del mago.', 'imagenes/El mago de oz/MagodeOz_portada_1.jpg', 'mago_oz.pdf', 'Aventura fantástica: Dorothy se une al Espantapájaros, el Hombre de Hojalata y el León Cobarde para pedir al Mago de Oz las cualidades que creen no tener: cerebro, corazón y valor.', 'Dorothy, Toto, Espantapajaros, Hombre de Hojalata, Leon Cobarde, Mago de Oz, Glinda, Bruja Malvada del Oeste', 'Aventura y fantasía', 'imagenes/El mago de oz/MagodeOz_portada_2.jpg'),
(9, 'Los crímenes de la calle Morgue', 'Edgar Allan Poe', 'Misterio policial donde Dupin resuelve un brutal doble asesinato en Paris.', 'imagenes/Los crímenes de la calle morgan/CrimenesCalleMorgan_portada_1.jpg', 'crimenes_morgue.pdf', 'Relato fundacional del cuento policial: Dupin demuestra que la razón y la observación minuciosa pueden explicar lo aparentemente inexplicable.', 'Dupin, Narrador, Madame L Espanaye, Mademoiselle Camille, Policia de Paris, Orangutan', 'Policial y de misterio', 'imagenes/Los crímenes de la calle morgan/CrímenesCalleMorgan_portada_2.jpg'),
(10, 'Cuentos y leyendas americanos', 'Varios autores', 'Relatos tradicionales sobre animales y heroes de America.', 'imagenes/CuentosLeyendasAmer_portada_1.jpg', 'cuentos_leyendas_americanos.pdf', 'Selección de relatos tradicionales sobre animales míticos, héroes, espíritus de la naturaleza y transformaciones; incluye enseñanzas morales y símbolos ancestrales.', 'Sapo, Condor, Tigre, Venado, Copil, Maese Falco, Raposa, Jaguar', 'Aventura y fantasía', 'imagenes/CuentosLeyendasAmer_portada_2.jpg'),
(11, 'Alicia en el país de las maravillas', 'Lewis Carroll', 'Alicia cae en una madriguera y entra a un mundo donde todo es extraño e impredecible.', 'imagenes/Alicia en el país de las maravillas/Alicia_portada_1.jpg', 'alicia_maravillas.pdf', 'Alicia persigue a un Conejo Blanco y cae por una madriguera hacia un mundo extraordinario lleno de criaturas parlantes, acertijos sin sentido, cambios de tamaño constantes y personajes excéntricos como el Sombrerero Loco, el Gato de Cheshire y la temible Reina de Corazones. En su viaje, Alicia enfrenta situaciones absurdas que desafían toda lógica.', 'Alicia, Conejo Blanco, Sombrerero Loco, Liebre de Marzo, Reina de Corazones, Gato de Cheshire, Oruga Azul, Rey de Corazones, Duquesa, Bill el Lagarto', 'Aventura y fantasía', 'imagenes/Alicia en el país de las maravillas/Alicia_portada_2.jpg'),
(12, 'Cien tradiciones peruanas', 'Ricardo Palma', 'Relatos que mezclan historia, leyenda y humor del Perú colonial.', 'imagenes/Cien tradiciones peruanas/CienTradiciones_portada_1.jpg', 'cien_tradiciones_peruanas.pdf', 'Las tradiciones peruanas son relatos costumbristas donde Palma convierte hechos históricos en cuentos llenos de ingenio. Con un estilo ágil e irónico, pinta cuadros del pasado limeño: procesiones religiosas, disputas legales, romances escondidos y travesuras de criollos que burlan a poderosos. Estas historias, llenas de humor y moralejas, nos permiten descubrir cómo vivían, pensaban y soñaban los peruanos de hace siglos.', 'Don Dimas (escribano astuto), Fray Gómez (fraile milagroso), Margarita, virreyes, damas coloniales, devotos del Señor de los Milagros, nobles y pícaros limeños', 'Tradiciones y cuentos', 'imagenes/Cien tradiciones peruanas/CienTradiciones_portada_2.jpg'),
(13, 'El Caballero Carmelo', 'Abraham Valdelomar', 'Historia de un gallo de pelea que simboliza honor y nobleza en el campo.', 'imagenes/El caballero carmelo/CaballeroCarmelo_portada_1.jpg', 'caballero_carmelo.pdf', 'El Caballero Carmelo sigue a un joven que se convierte en el mejor amigo de un caballo, Carmelo. Juntos, atraviesan las dificultades de un mundo rural en transformación, donde el amor, la amistad y la pérdida marcan su camino. La historia es un retrato conmovedor de la vida en el campo y la lucha por encontrar un lugar en la sociedad.', 'Carmelo (el gallo), José (protagonista soñador), Don Manuel (anciano sabio), María (interés amoroso), Don Pedro (terrateniente antagonista), Roberto (hermano mayor)', 'Tradiciones y cuentos', 'imagenes/El caballero carmelo/CaballeroCarmelo_portada_2.jpg'),
(14, 'La Metamorfosis', 'Franz Kafka', 'Un hombre despierta convertido en insecto y enfrenta el rechazo familiar.', 'imagenes/La metamorfosis/Metamorfosis_portada_1.jpg', 'metamorfosis.pdf', 'La metamorfosis explora la tragedia de Gregorio Samsa, un hombre que vive para mantener a su familia y que, tras convertirse en un insecto, se vuelve una carga. El relato desnuda la crueldad del abandono, la deshumanización y el valor efímero que la sociedad asigna al individuo. Kafka retrata un mundo frío y burocrático donde el afecto se quiebra ante lo inútil.', 'Gregorio Samsa (vendedor viajante), Grete Samsa (hermana), Señor y Señora Samsa (padres), Jefe de Gregorio, Inquilinos, Sirvienta', 'Drama', 'imagenes/La metamorfosis/Metamorfosis_portada_2.jpg'),
(15, 'Las Aventuras de Sherlock Holmes', 'Arthur Conan Doyle', 'El detective más brillante resuelve enigmas con deducción y lógica.', 'imagenes/Las aventuras de sherlock holmes/SherlockHolmes_portada_1.jpg', 'sherlock_holmes.pdf', 'Esta colección reúne doce relatos donde Sherlock Holmes despliega su incomparable capacidad de observación y deducción. Entre chantajes, misteriosas desapariciones y crímenes aparentemente perfectos, Holmes y Watson descubren la verdad oculta tras cada enigma. Los primeros cinco casos introducen a los lectores en el arte del razonamiento lógico y la astucia detectivesca.', 'Sherlock Holmes (detective), Dr. Watson (médico y narrador), Inspector Lestrade, Irene Adler (la mujer), Rey de Bohemia, Jabez Wilson, James McCarthy, John Turner, John Openshaw', 'Policial y de misterio', 'imagenes/Las aventuras de sherlock holmes/SherlockHolmes_portada_2.jpg'),
(16, 'Mitos y leyendas de Arequipa', 'Tradición Oral Arequipeña', 'Relatos donde lo real y lo fantástico revelan la cosmovisión andina.', 'imagenes/Mitos y leyendas de arequipa/MitosLeyendasAQP_portada_1.jpg', 'mitos_arequipa.pdf', 'El libro comienza con una introducción teórica que explica qué son los mitos y leyendas, su estructura y función dentro de la cultura andina. Luego, invita a recorrer la tradición oral de Arequipa a través de relatos donde lo religioso, lo sobrenatural y lo cotidiano se entrelazan. Almas en pena, demonios, duendes y sirenas habitan volcanes y ríos, revelando la esencia del folklore arequipeño. Más que una simple recopilación, esta obra es un viaje cultural que preserva la memoria, los valores y la identidad de un pueblo.', 'Mónica la condenada, El Diablo de la Catedral, El Inca (Chaco Pesca), La joven del Puente del Diablo, El Hijo del Misti (Misticito), Los Gentiles', 'Tradiciones y cuentos', 'imagenes/Mitos y leyendas de arequipa/MitosLeyendasAQP_portada_2.jpg'),
(17, 'Un mundo para Julius', 'Alfredo Bryce Echenique', 'La mirada inocente de un niño revela la hipocresía aristocrática.', 'imagenes/Un mundo para julius/MundoJulius_portada_1.jpg', 'mundo_julius.pdf', 'En la Lima de mediados del siglo XX, Julius crece rodeado de lujos, sirvientes y apariencias dentro de una familia rica pero emocionalmente vacía. Su mirada infantil desnuda las tensiones entre clases, el racismo, la indiferencia y la falta de afecto que reinan en su entorno. Mientras Julius intenta comprender el mundo que lo rodea, se enfrenta a la pérdida de la inocencia y al dolor de descubrir que detrás de la riqueza se ocultan el egoísmo, la soledad y la injusticia social.', 'Julius (niño sensible e inocente), Susan (madre elegante y distante), Juan Lucas (padrastro frívolo y poderoso), Vilma y Nilda (empleadas que dan ternura), Santiago y Bobby (hermanos duros), Cynthia (hermana superficial)', 'Drama', 'imagenes/Un mundo para julius/MundoJulius_portada_2.jpg'),
(18, 'La vuelta al mundo en 80 días', 'Julio Verne', 'Una audaz apuesta contra el tiempo que desafía lo imposible.', 'imagenes/La vuelta al mundo en 80 días/VueltaMundo_portada_1.jpg', 'vuelta_mundo_80_dias.pdf', 'La vida de Phileas Fogg, un hombre de rutinas inquebrantables, se ve sacudida por una audaz apuesta en su club de Londres. Acompañado por su leal y recién contratado mayordomo, Passepartout, se embarca en una aventura épica. Sin embargo, el detective Fix de Scotland Yard está convencido de que Fogg es un fugitivo y lo perseguirá sin descanso. Una historia de honor, lealtad y los imprevistos que desafían la lógica más estricta.', 'Phileas Fogg (caballero inglés metódico y puntual), Jean Passepartout (mayordomo francés acrobático y leal), Detective Fix (inspector de Scotland Yard que persigue a Fogg), Aouda (princesa india rescatada), Sir Francis Cromarty (oficial británico), Miembros del Reform Club', 'Aventura y fantasía', 'imagenes/La vuelta al mundo en 80 días/VueltaMundo_portada_2.jpg');
INSERT INTO `preguntas` (`id_pregunta`, `id_libro`, `id_capitulo`, `numero_pregunta`, `enunciado`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `puntaje`) VALUES
(1, 1, '1', 1, '¿Dónde se encuentra físicamente el protagonista al inicio del fragmento?', 'En el patio del colegio militar.', 'En una garita de vigilancia.', 'En los corredores vacíos.', 'En su casa junto a su madre.', 'B', 20),
(2, 1, '1', 2, 'Según el texto, ¿cuál era la expectativa del Esclavo antes de ingresar al Leoncio Prado?', 'Aprender a usar un fusil con destreza.', 'Encontrar un ambiente de orden y camaradería.', 'Formar parte del Círculo liderado por el Jaguar.', 'Sobrevivir a base de alianzas frágiles y pactos.', 'B', 20),
(3, 1, '1', 3, '¿Qué efecto visual provoca la neblina sobre el patio del colegio?', 'Hace que la noche parezca un manto sofocante.', 'Oculta totalmente la presencia de los oficiales.', 'Difumina las sombras y alarga visualmente los corredores.', 'Permite ver claramente las amenazas en cada rincón.', 'C', 20),
(4, 1, '1', 4, 'De acuerdo con el fragmento, ¿quiénes ejercen el poder real dentro de la institución?', 'Los oficiales del ejército.', 'La madre del protagonista desde la distancia.', 'El Jaguar y el Círculo.', 'El Esclavo mediante su fusil.', 'C', 20),
(5, 1, '1', 5, '¿Qué representa la “añoranza” para el Esclavo en el fragmento mejorado?', 'Una debilidad que se paga muy caro en el colegio.', 'El único espacio personal donde aún no ha sido vencido.', 'Una moneda diaria para pagar por la brutalidad.', 'El motivo por el cual sus manos están tensas al sostener el arma.', 'B', 20),
(6, 1, '2', 1, '¿Por qué Cava camina con tanta cautela por el colegio militar?', 'Porque el suelo estaba resbaloso', 'Porque no quería que sus pasos lo delataran', 'Porque había mucha gente despierta', 'Porque temía encontrarse con Alberto', 'B', 20),
(7, 1, '2', 2, '¿Qué efecto provoca la neblina descrita como “manto opaco que distorsiona las sombras”?', 'Crea un ambiente misterioso y tenso', 'Da una sensación de tranquilidad', 'Ayuda a Cava a sentirse protegido', 'Sirve para iluminar el camino', 'A', 20),
(8, 1, '2', 3, '¿Qué representa para Cava el “desprecio implacable del Jaguar”?', 'Un castigo físico inevitable', 'La pérdida del único respaldo que lo protege', 'Un simple enojo pasajero', 'Una oportunidad para ganar respeto', 'B', 20),
(9, 1, '2', 4, '¿Qué sensación produce el aire “viciado y pesado” del aula?', 'Frescura y alivio', 'incomodidad y encierro', 'Protección frente al peligro', 'Un espacio seguro para descansar', 'B', 20),
(10, 1, '2', 5, '¿Qué refleja la reacción del Jaguar al enterarse del vidrio roto?', 'Su indiferencia ante el riesgo', 'Su frialdad y falta de compasión', 'Su sorpresa y miedo', 'Su deseo de ayudar a Cava', 'B', 20),
(11, 1, '3', 1, '¿Por qué Cava no temblaba por el frío del aire nocturno?', 'Porque estaba acostumbrado al clima de la sierra', 'Porque el edificio estaba bien cerrado', 'Porque su miedo era más intenso que el frío', 'Porque el Jaguar le había dado valor', 'C', 20),
(12, 1, '3', 2, '¿Qué significa que “el azar de los dados había decidido su destino”?', 'Que estaba jugando en ese momento', 'Que todo lo que hacía dependía de la suerte', 'Que tenía libertad para elegir', 'Que el colegio premiaba los juegos', 'B', 20),
(13, 1, '3', 3, '¿Qué sensación provocaba el ambiente de la cuadra mientras todos dormían?', 'Una tranquilidad que calmaba a Cava', 'Un silencio roto por olores rancios y murmullos inquietantes', 'Una paz que contrastaba con sus pensamientos', 'Una seguridad que lo reconfortaba', 'B', 20),
(14, 1, '3', 4, '¿Qué revela la frase “la humillación era una moneda diaria”?', 'Que todos recibían premios por su conducta', 'Que la humillación era algo frecuente y cotidiano', 'Que solo los débiles sufrían castigos', 'Que se intercambiaba como dinero', 'B', 20),
(15, 1, '3', 5, '¿Qué representa el frío “que no nacía del clima sino del miedo”?', 'Que el edificio era demasiado helado', 'Que el colegio estaba en una zona muy fría', 'Que el verdadero frío era emocional, provocado por el terror', 'Que el Jaguar controlaba la temperatura del lugar', 'C', 20),
(16, 1, '4', 1, '¿Qué revela la conversación entre Alberto y su madre sobre la familia?', 'Que es un hogar estable y feliz', 'Que la madre aún ama profundamente a su esposo', 'Que la familia está marcada por el abandono y el dolor', 'Que Alberto no siente nada por su madre', 'C', 20),
(17, 1, '4', 2, '¿Cómo se siente Alberto al escuchar el regreso de su padre?', 'Aliviado por la reconciliación', 'Resentido y atrapado entre el rencor y la compasión', 'Indiferente porque ya no le importa', 'Alegre porque confía en las promesas del padre', 'B', 20),
(18, 1, '4', 3, '¿Qué simboliza el sobre con dinero que recibe Alberto?', 'Un acto sincero de amor paternal', 'Un intento superficial de comprar afecto', 'Una simple ayuda económica sin importancia', 'Un gesto para reconciliar a toda la familia', 'B', 20),
(19, 1, '4', 4, '¿Por qué la casa no logra darle paz a Alberto?', 'Porque está llena de recuerdos rotos y dolor', 'Porque su madre lo rechaza', 'Porque extraña la violencia del colegio', 'Porque solo piensa en el dinero', 'A', 20),
(20, 1, '4', 5, '¿Qué sensación deja la escena final entre Alberto y su madre?', 'Esperanza en una nueva vida', 'Desolación y ternura mezcladas', 'Alegría por el regreso del padre', 'Confianza en que todo mejorará', 'B', 20),
(21, 1, '5', 1, '¿Qué sensación le produce a Alberto caminar por Miraflores con sus amigos?', 'Alegría por sentirse libre', 'Indiferencia total ante el ambiente', 'Extrañeza y desconexión, como si fuera un lugar ilusorio', 'Tranquilidad por estar lejos del colegio', 'C', 20),
(22, 1, '5', 2, '¿Qué simbolizan las fachadas ostentosas y los jardines geométricamente podados?', 'El orden y la belleza de Lima', 'Una vida llena de disciplina y equilibrio', 'Una apariencia superficial que oculta vacíos más profundos', 'El verdadero refugio de los jóvenes limeños', 'C', 20),
(23, 1, '5', 3, '¿Por qué la presencia de Teresa contrasta con las demás chicas del paseo?', 'Porque es tímida y no busca llamar la atención', 'Porque es la más rica del grupo', 'Porque se comporta igual que las demás, pero con más elegancia', 'Porque habla más que todas y rompe la frivolidad', 'A', 20),
(24, 1, '5', 4, '¿Qué reflexión tiene Alberto al final sobre Miraflores y el colegio militar?', 'Que son dos mundos opuestos e irreconciliables', 'Que ambos son escenarios donde existen diferentes formas de sometimiento', 'Que la ciudad ofrece libertad y el colegio represión', 'Que la sociedad civil es siempre mejor que la militar', 'B', 20),
(25, 1, '5', 5, '¿Qué significa la idea de “cárceles invisibles” en este capítulo?', 'Que las personas viven encerradas en lugares físicos', 'Que existen normas y jerarquías ocultas que limitan la libertad', 'Que Miraflores es tan seguro que parece una cárcel', 'Que el colegio militar vigila a todos incluso fuera de sus muros', 'B', 20),
(26, 2, '1', 1, '¿Cuál es el propósito principal del viaje de Jonathan Harker a Transilvania?', 'Conocer nuevas culturas', 'Investigar fenómenos paranormales', 'Cerrar la compra de una propiedad para un cliente', 'Huir de su vida en Londres', 'C', 20),
(27, 2, '1', 2, '¿Cómo reaccionan los lugareños al saber que Jonathan va al castillo del conde Drácula?', 'Lo animan a seguir su camino', 'Le advierten con temor y le dan amuletos', 'Lo ignoran completamente', 'Se ofrecen a acompañarlo', 'B', 20),
(28, 2, '1', 3, '¿Qué aspecto tiene el conde Drácula cuando Jonathan lo conoce?', 'Enérgico, alegre y saludable', 'Alto, pálido, con dientes afilados y comportamiento inquietante', 'Joven, de cabello rubio y mirada bondadosa', 'Anciano, débil y enfermo', 'B', 20),
(29, 2, '1', 4, '¿Qué fenómeno inquietante ocurre durante el trayecto en carruaje hacia el castillo?', 'Nieva intensamente', 'Aparece una figura espectral', 'Los lobos aúllan y el cochero parece tener control sobre ellos', 'Jonathan se queda dormido misteriosamente', 'C', 20),
(30, 2, '1', 5, '¿Qué sensación predomina al final del fragmento?', 'Triunfo y alivio', 'Diversión y curiosidad', 'Aislamiento y misterio', 'Esperanza y confianza', 'C', 20),
(31, 2, '1', 1, '¿Cuál es el propósito principal del viaje de Jonathan Harker a Transilvania?', 'Conocer nuevas culturas', 'Investigar fenómenos paranormales', 'Cerrar la compra de una propiedad para un cliente', 'Huir de su vida en Londres', 'C', 20),
(32, 2, '1', 2, '¿Cómo reaccionan los lugareños al saber que Jonathan va al castillo del conde Drácula?', 'Lo animan a seguir su camino', 'Le advierten con temor y le dan amuletos', 'Lo ignoran completamente', 'Se ofrecen a acompañarlo', 'B', 20),
(33, 2, '1', 3, '¿Qué aspecto tiene el conde Drácula cuando Jonathan lo conoce?', 'Enérgico, alegre y saludable', 'Alto, pálido, con dientes afilados y comportamiento inquietante', 'Joven, de cabello rubio y mirada bondadosa', 'Anciano, débil y enfermo', 'B', 20),
(34, 2, '1', 4, '¿Qué fenómeno inquietante ocurre durante el trayecto en carruaje hacia el castillo?', 'Nieva intensamente', 'Aparece una figura espectral', 'Los lobos aúllan y el cochero parece tener control sobre ellos', 'Jonathan se queda dormido misteriosamente', 'C', 20),
(35, 2, '1', 5, '¿Qué sensación predomina al final del fragmento?', 'Triunfo y alivio', 'Diversión y curiosidad', 'Aislamiento y misterio', 'Esperanza y confianza', 'C', 20),
(36, 2, '2', 1, '¿Qué propiedad ha comprado el conde Drácula en Inglaterra?', 'Whitby Abbey', 'Carfax', 'Highgate Manor', 'Westfield House', 'B', 20),
(37, 2, '2', 2, '¿Qué rasgo físico de Drácula empieza a alarmar a Jonathan Harker?', 'Su barba larga y blanca', 'Su aliento a ajo', 'Sus orejas puntiagudas, piel pálida y uñas afiladas', 'Su cojera y mirada ciega', 'C', 20),
(38, 2, '2', 3, '¿Qué ocurre cuando Jonathan ve que Drácula no se refleja en el espejo?', 'Piensa que está alucinando', 'El conde rompe el espejo violentamente', 'Corre a su habitación y se encierra', 'Drácula huye', 'B', 20),
(39, 2, '2', 4, '¿Qué descubre Jonathan sobre las puertas del castillo?', 'Todas tienen cerraduras rotas', 'Todas están abiertas, pero llevan a pasadizos secretos', 'Todas están cerradas con llave y no tiene acceso libre', 'Hay guardias vigilando cada puerta', 'C', 20),
(40, 2, '2', 5, '¿Cuál es la principal emoción de Jonathan al final del fragmento?', 'Curiosidad por lo desconocido', 'Euforia por la aventura', 'Angustia y sensación de estar atrapado', 'Nostalgia por Londres', 'C', 20),
(41, 2, '3', 1, '¿Qué le pide el conde Drácula a Jonathan respecto a cartas para su familia y jefe?', 'Que no escriba para evitar sospechas', 'Que escriba cartas fechadas hacia el futuro como si todo estuviera bien', 'Que les diga que está atrapado', 'Que no mencione el castillo', 'B', 20),
(42, 2, '3', 2, '¿Qué prohibición le da el conde Drácula a Jonathan?', 'No usar espejos en el castillo', 'No escribir en su diario', 'No deambular por el castillo mientras él duerme', 'No abrir las ventanas', 'C', 20),
(43, 2, '3', 3, '¿Qué ocurre cuando Jonathan explora el castillo por la noche?', 'Encuentra una salida secreta', 'Se encuentra con el conde transformado en murciélago', 'Es atacado por tres mujeres vampiro', 'Descubre a otros prisioneros', 'C', 20),
(44, 2, '3', 4, '¿Qué promete Drácula a las mujeres vampiro para calmarlas?', 'Que pronto dejarán el castillo', 'Que traerá a Jonathan como ofrenda', 'Que les permitirá ir a Londres', 'Que les traerá un niño como presa', 'D', 20),
(45, 2, '3', 5, '¿Qué función cumple el diario de Jonathan en esta etapa de la historia?', 'Le sirve como prueba legal contra Drácula', 'Es un recurso para practicar su inglés', 'Es su única forma de conservar la cordura ante lo sobrenatural', 'Lo usa para comunicarse en secreto con Mina', 'C', 20),
(46, 2, '4', 1, '¿Qué habilidad sobrenatural demuestra Drácula frente a Jonathan?', 'Convertirse en lobo', 'Volar por las torres del castillo', 'Desplazarse por las paredes como un lagarto', 'Leer la mente de Jonathan', 'C', 20),
(47, 2, '4', 2, '¿Qué hace Jonathan para protegerse de posibles envenenamientos?', 'Solo come frutas', 'Ayuna completamente', 'Solo come alimentos traídos por él mismo', 'Cocina su propia comida', 'C', 20),
(48, 2, '4', 3, '¿Qué descubre Jonathan en la biblioteca secreta del castillo?', 'Una salida oculta', 'El diario personal de Drácula', 'El linaje y pasado guerrero del conde', 'Instrucciones para matar vampiros', 'C', 20),
(49, 2, '4', 4, '¿Qué deduce Jonathan al ver a Drácula con un saco que se mueve?', 'Que transporta objetos robados', 'Que está ocultando comida', 'Que lleva un niño como ofrenda a las vampiresas', 'Que se va de caza', 'C', 20),
(50, 2, '4', 5, '¿Cuál es el objetivo de Jonathan al dejar su diario escrito?', 'Tener algo con qué distraerse', 'Documentar su vida cotidiana', 'Advertir al mundo sobre Drácula si muere', 'Escribir una novela en el futuro', 'C', 20),
(51, 2, '5', 1, '¿Qué cambio importante ocurre en este capítulo respecto a los anteriores?', 'Se presenta a un nuevo vampiro', 'Se cambia el narrador y el lugar de la historia', 'Drácula llega a Inglaterra', 'Jonathan escapa del castillo', 'B', 20),
(52, 2, '5', 2, '¿Desde qué lugar escribe Mina Murray sus cartas?', 'Londres', 'Transilvania', 'Whitby', 'Edimburgo', 'C', 20),
(53, 2, '5', 3, '¿Cuántas propuestas de matrimonio recibe Lucy Westenra en un solo día?', 'Dos', 'Tres', 'Cuatro', 'Una', 'B', 20),
(54, 2, '5', 4, '¿Cuál de los pretendientes es finalmente aceptado por Lucy?', 'John Seward', 'Quincey P. Morris', 'Arthur Holmwood', 'Jonathan Harker', 'C', 20),
(55, 2, '5', 5, '¿Qué elemento sugiere que, a pesar de la aparente paz, algo oscuro se avecina?', 'Lucy tiene pesadillas', 'El clima es cambiante y hay inquietud en Mina', 'Drácula es visto en Whitby', 'Los pretendientes discuten entre sí', 'B', 20),
(56, 3, '1', 1, '¿A quien le cuenta Victor Frankenstein su historia?', 'A su madre', 'A un medico', 'A Robert Walton', 'A Elizabeth Lavenza', 'C', 20),
(57, 3, '1', 2, '¿En que situacion se encuentra Victor cuando comienza su relato?', 'Atrapado en el hielo del Ártico', 'Refugiado en una cueva', 'Viajando con su familia', 'Estudiando en la universidad', 'A', 20),
(58, 3, '1', 3, '¿Que motivo impulsa a Robert Walton en su expedicion?', 'Buscar nuevas especies animales', 'Demostrar la existencia del Polo Norte', 'Descubrir una ruta hacia el Pacifico por el norte', 'Encontrar oro y riquezas', 'C', 20),
(59, 3, '1', 4, '¿Como describe Walton a Victor cuando lo encuentra?', 'Fuerte y saludable', 'Debil, exhausto y casi sin vida', 'Enojado y violento', 'Sereno y filosofico', 'B', 20),
(60, 3, '1', 5, '¿Que valor comun une a Walton y a Victor al conocerse?', 'El amor por la familia', 'La fe religiosa', 'La ambicion por el conocimiento y la gloria', 'El deseo de venganza', 'C', 20),
(61, 3, '2', 1, '¿Quienes conformaban el circulo cercano de Victor durante su infancia?', 'Sus hermanos menores y un tutor', 'Elizabeth y un sacerdote', 'Elizabeth y Henry Clerval', 'Henry Clerval y un profesor de ciencias', 'C', 20),
(62, 3, '2', 2, '¿Que tipo de autores fascinaban a Victor durante su juventud?', 'Poetas romanticos como Byron y Shelley', 'Cientificos modernos como Newton y Faraday', 'Ocultistas antiguos como Agrippa, Paracelso y Albertus Magnus', 'Novelistas del siglo XVIII', 'C', 20),
(63, 3, '2', 3, '¿Como reacciono el padre de Victor al ver el libro de Cornelio Agrippa?', 'Le dijo que era un gran autor', 'Le explico que era un texto interesante pero anticuado', 'Lo animo a seguir leyendo', 'Lo desprecio sin explicar por que', 'D', 20),
(64, 3, '2', 4, '¿Que evento natural impacto profundamente a Victor?', 'La muerte de su madre', 'Un eclipse total', 'Un rayo que destruyo un arbol', 'Una nevada temprana', 'C', 20),
(65, 3, '2', 5, '¿Que transicion intelectual empieza a vivir Victor al final del capitulo?', 'De la religion a la politica', 'Del arte a la ciencia empirica', 'De la supersticion a la ciencia moderna', 'De la literatura a la poesia', 'C', 20),
(66, 3, '3', 1, '¿Que evento personal marca profundamente a Victor al inicio del capitulo?', 'El nacimiento de su hermano menor', 'La muerte de su madre por escarlatina', 'El rechazo de Elizabeth', 'Un accidente en la universidad', 'B', 20),
(67, 3, '3', 2, '¿Cual es el deseo final de Caroline Beaufort antes de morir?', 'Que Victor se convierta en medico', 'Que Elizabeth se mude a Inglaterra', 'Que Victor y Elizabeth se casen', 'Que Henry Clerval estudie en Ingolstadt', 'C', 20),
(68, 3, '3', 3, '¿Como reacciona M. Krempe cuando Victor menciona a los antiguos alquimistas?', 'Con interes y entusiasmo', 'Con respeto academico', 'Con desden y burla', 'Con neutralidad cientifica', 'C', 20),
(69, 3, '3', 4, '¿Que diferencia a M. Waldman de M. Krempe en su trato con Victor?', 'Waldman tambien desprecia la alquimia', 'Waldman muestra comprension y pasion por la ciencia', 'Waldman no cree en la educacion formal', 'Waldman prohibe a Victor estudiar quimica', 'B', 20),
(70, 3, '3', 5, '¿Que sentimiento despierta el discurso de Waldman en Victor?', 'Indiferencia hacia la ciencia', 'Deseo de abandonar la universidad', 'Un llamado emocional a descubrir los secretos de la vida', 'Miedo al conocimiento prohibido', 'C', 20),
(71, 3, '4', 1, '¿Que transforma el interes de Victor Frankenstein en una obsesion total?', 'La muerte de Elizabeth', 'El deseo de vengar a su madre', 'Su afan por descubrir el principio de la vida', 'Las burlas de sus companeros', 'C', 20),
(72, 3, '4', 2, '¿Que acciones realiza Victor para investigar la muerte y la vida?', 'Asiste a clases de medicina solamente', 'Experimenta con animales vivos', 'Visita morgues y disecciona cadaveres', 'Consulta libros religiosos', 'C', 20),
(73, 3, '4', 3, '¿Por que Victor decide que su criatura sera de gran tamano?', 'Para poder verla desde lejos', 'Porque su laboratorio era muy grande', 'Porque asi seria mas fuerte que un humano', 'Porque trabajar con piezas pequenas era mas dificil', 'D', 20),
(74, 3, '4', 4, '¿Como describe Victor a su creacion durante el proceso de construccion?', 'Como un monstruo aterrador', 'Como un ser bello', 'Como una maquina viviente', 'Como un experimento arriesgado', 'B', 20),
(75, 3, '4', 5, '¿Que senales indican el creciente desequilibrio emocional de Victor?', 'Comienza a escribir poesia y cantar', 'Se obsesiona con su amigo Clerval', 'Se aisla, descuida su salud y abandona todo contacto personal', 'Quiere convertirse en profesor universitario', 'C', 20),
(76, 3, '5', 1, '¿Que ocurre finalmente en este capitulo que lo convierte en uno de los mas importantes de la novela?', 'Victor regresa a casa con su familia', 'Victor da vida a su creacion', 'El monstruo destruye el laboratorio', 'Henry descubre el experimento', 'B', 20),
(77, 3, '5', 2, '¿Cual es la reaccion de Victor al ver viva a su criatura?', 'Euforia y orgullo', 'Curiosidad cientifica', 'Terror, remordimiento y rechazo', 'Comienza a ensenarle a hablar', 'C', 20),
(78, 3, '5', 3, '¿Que papel desempena Henry Clerval en este fragmento?', 'Acusa a Victor de ser un criminal', 'Ayuda a Victor a continuar sus experimentos', 'Cuida de Victor durante su enfermedad', 'Se une a la criatura para vengarse', 'C', 20),
